export async function POST(req: NextRequest) {
  try {
    const { message, visitorId } = await req.json();

    if (typeof message !== "string" || message.length > 4000 || typeof visitorId !== "string" || !/^[A-Za-z0-9_-]{1,128}$/.test(visitorId)) {
      return NextResponse.json({ error: 'Missing required fields' }, { status: 400 });
    }

    const rate = await checkRateLimit(req, null, 'landing', { windowMs: 60000, maxRequests: 5 });
    if (!rate.allowed) return NextResponse.json({ error: rate.error }, { status: 429 });

    let currentCount = 0;
    let visitorRef: any = null;
    if (adminDb && typeof adminDb.collection === 'function') {
      try {
        visitorRef = adminDb.collection('landing_visitors').doc(visitorId);
        const visitorDoc = await visitorRef.get();
        currentCount = visitorDoc.exists ? (visitorDoc.data()?.messageCount ?? 0) : 0;
      } catch (dbErr) {
        console.warn('[Landing Chat] Firestore visitor check failed:', dbErr);
      }
    }

    if (currentCount >= LANDING_LIMIT) {
      return NextResponse.json({
        error: `You've reached the ${LANDING_LIMIT}-message demo limit. Sign up for unlimited access.`,
        limitReached: true,
      }, { status: 429 });
    }

    if (visitorRef) {
      try {
        await visitorRef.set({
          messageCount: currentCount + 1,
          lastMessageAt: new Date(),
          visitorId,
          ...(currentCount === 0 ? { firstMessageAt: new Date() } : {}),
        }, { merge: true });
      } catch (dbErr) {
        console.warn('[Landing Chat] Firestore visitor increment failed:', dbErr);
      }
    }

    // Generate AI response (server-side direct REST call — avoids firebase/ai client SDK in Cloud Run)
    const result = await billingContext.run({ organizationId: LANDING_ORG_ID || "", type: "landing" }, () => callGeminiDirect(`${LANDING_SYSTEM_PROMPT}\n\nVisitor question: ${message}`));

    const remaining = LANDING_LIMIT - (currentCount + 1);

    return NextResponse.json({
      text: result.text,
      remaining,
    });
  } catch (error: any) {
    console.error('[Landing Chat API] Error:', error);
    return NextResponse.json({
      error: error?.message || 'Internal server error',
    }, { status: 500 });
  }
}

import { withAuthorizedRequest } from "@/lib/auth-verify";
import { NextRequest, NextResponse } from 'next/server';
import { adminDb } from '@/lib/firebase-admin';
import { getNetworkLimitsHelp } from '@/lib/ai/network';
import type { NetworkLimitsContext } from '@/lib/ai/network';
import { checkBudget, recordUsage } from '@/lib/usage-limit';

async function handlePost(req: NextRequest) {
  try {
    const { message, chatHistory, userId } = await req.json();

    if (!message || !userId) {
      return NextResponse.json({ error: 'Missing required fields' }, { status: 400 });
    }

    if (!adminDb) {
      return NextResponse.json({ error: 'Service unavailable' }, { status: 503 });
    }

    // 1. Resolve user + org
    const userDoc = await adminDb.collection('users').doc(userId).get();
    if (!userDoc.exists) {
      return NextResponse.json({ error: 'User not found' }, { status: 404 });
    }
    const userData = userDoc.data();
    const organizationId = userData?.organizationId;

    if (!organizationId) {
      return NextResponse.json({ error: 'No network associated with this account' }, { status: 403 });
    }

    // 2. Budget check
    const budgetCheck = await checkBudget(organizationId, 'navigation');
    if (!budgetCheck.allowed) {
      return NextResponse.json({ error: budgetCheck.error }, { status: 403 });
    }

    // 3. Fetch org data for context
    const orgDoc = await adminDb.collection('organizations').doc(organizationId).get();
    if (!orgDoc.exists) {
      return NextResponse.json({ error: 'Organization not found' }, { status: 404 });
    }
    const orgData = orgDoc.data()!;

    // 4. Count students for the network
    let studentCount = 0;
    try {
      const teacherSnap = await adminDb.collection('users')
        .where('organizationId', '==', organizationId)
        .where('role', '==', 'teacher')
        .get();
      const teacherIds = teacherSnap.docs.map(d => d.id);
      if (teacherIds.length > 0) {
        const studentsSnap = await adminDb.collection('users')
          .where('teacherId', 'in', teacherIds.slice(0, 10))
          .where('role', '==', 'student')
          .get();
        studentCount = studentsSnap.size;
      }
    } catch (e) {
      console.error('Student count error:', e);
    }

    // 5. Build context object
    const ctx: NetworkLimitsContext = {
      orgName: orgData.name || 'Your Network',
      planId: orgData.planId || 'free',
      aiBudgetLimit: orgData.aiBudgetLimit || 0,
      aiUsageCurrent: orgData.aiUsageCurrent || 0,
      notebookLimitPerStudent: orgData.notebookLimitPerStudent || 0,
      aiNotebookLimitPerStudent: orgData.aiNotebookLimitPerStudent || 0,
      aiTutorLimitPerStudent: orgData.aiTutorLimitPerStudent || 0,
      studentCount,
    };

    // 6. Generate response
    const result = await getNetworkLimitsHelp(message, chatHistory || [], ctx);

    // 7. Record usage
    if (result.usage) {
      await recordUsage(organizationId, 'navigation', result.usage.inputTokens, result.usage.outputTokens);
    }

    return NextResponse.json({ text: result.text });
  } catch (error: any) {
    console.error('Limits assistant error:', error);
    return NextResponse.json({ error: error?.message || 'Internal server error' }, { status: 500 });
  }
}

