    }

    if (!organizationId) {
        return NextResponse.json({ error: "No organization found for grading budget." }, { status: 403 });
    }

    const budgetCheck = await checkBudget(organizationId, "grading");
    if (!budgetCheck.allowed) {
        return NextResponse.json({ error: budgetCheck.error }, { status: 403 });
    }

    // 1.5 Resolve Student Names for PII Scrubbing
    let studentNames: string[] = [];
    try {
      const teacherId = studentData?.teacherId;
      if (teacherId) {
        const studentsSnapshot = await adminDb.collection("users")
          .where("teacherId", "==", teacherId)
          .where("role", "==", "student")
          .get();

        studentNames = studentsSnapshot.docs.map(doc => doc.data().displayName || doc.data().name).filter(Boolean);
      }

      // Also include this student specifically
      const currentName = studentData?.displayName || studentData?.name;
      if (currentName && !studentNames.includes(currentName)) {
        studentNames.push(currentName);
      }
    } catch (e) {
      console.error("Error resolving student names for scrubbing:", e);
    }

    // 2. Fetch Assignment
    const assignmentSnap = await adminDb.collection('assignments').doc(assignmentId).get();

    if (!assignmentSnap.exists) {
      return NextResponse.json({ error: 'Assignment not found' }, { status: 404 });
    }

    const key = (await adminDb.collection("assignment_keys").doc(assignmentId).get()).data();
    const assignmentData = mergeAnswerKey(assignmentSnap.data()!, key);
    const questions = assignmentData?.questions || [];
    const answers = submissionData?.answers || []; 
    const globalRubric = assignmentData?.rubric || "";

    // 3. Grade
    let totalScore = 0;
    let maxScore = 0;

    // Calculate accurate maxScore from ALL questions in assignment
    for (const q of questions) {
      maxScore += (q.points || 10);
    }

    const gradedAnswers = [];
    let totalPromptTokens = 0;
    let totalCandidateTokens = 0;

    for (const ans of answers) {
      const question = questions.find((q: any) => q.id === ans.questionId);
      if (!question) {
        gradedAnswers.push(ans);
        continue;
      }

      const points = question.points || 10;
      // We already added points to maxScore above for all questions

      let score = 0;
      let feedback = "";
      let reasoning = "";

      // Improved Grading Logic: 
      // 1. Multiple Choice / True-False: Strict match
      // 2. Text / Short Answer: AI Grading for nuance
      if ((question.type === "text" || question.type === "short-answer") && ans.answer) {
        // AI Grading
        try {
            // Combine question-specific rubric (correctAnswer) with global rubric
            const combinedRubric = [question.correctAnswer, globalRubric].filter(Boolean).join("\n\nGlobal Assignment Rubric:\n");
            const result = await gradeResponse(question.text, ans.answer, combinedRubric, studentNames);
            feedback = result.feedback;
            reasoning = result.reasoning || "";

            // Track usage
            if (result.usage) {
                totalPromptTokens += result.usage.inputTokens;
                totalCandidateTokens += result.usage.outputTokens;
            }

            // Calculate score based on points
            // result.score is out of 10
            const rawScore = result.score; // 0-10
            score = (rawScore / 10) * points;

        } catch (e) {
            console.error("AI Grading failed", e);
            if (!submissionData?.graded) await submissionRef.update({ status: "pending_review", gradingError: "AI grading unavailable", graded: false });
            return NextResponse.json({ error: "AI grading failed. The existing grade was preserved; review manually or retry." }, { status: 502 });
        }
      } else if (question.correctAnswer && (question.type === "multiple-choice" || question.type === "true-false")) {
        // Strict match for objective questions
        const isCorrect = ans.answer.trim().toLowerCase() === question.correctAnswer.trim().toLowerCase();
        score = isCorrect ? points : 0;
        feedback = isCorrect ? "Correct!" : `Incorrect. The correct answer was: ${question.correctAnswer}`;
      } else if (question.correctAnswer) {
        // Fallback exact match for other types just in case
        const isCorrect = ans.answer.trim().toLowerCase() === question.correctAnswer.trim().toLowerCase();
        score = isCorrect ? points : 0;
        feedback = isCorrect ? "Correct!" : `Incorrect. Expected: ${question.correctAnswer}`;
      }

      totalScore += score;
      gradedAnswers.push({
        ...ans,
        feedback,
        reasoning,
        score,
        maxPoints: points
      });
    }

    // Record cumulative usage
    if (totalPromptTokens > 0 || totalCandidateTokens > 0) {
        await recordUsage(organizationId, "grading", totalPromptTokens, totalCandidateTokens);
    }

    const finalScore = maxScore > 0 ? Math.round((totalScore / maxScore) * 100) : 0;

    // 4. Update Submission
    await submissionRef.update({
      score: finalScore,
      totalPoints: maxScore,
      earnedPoints: totalScore,
      answers: gradedAnswers,
      graded: true,
      status: "graded",
      gradedAt: new Date()
    });

    return NextResponse.json({ success: true, score: finalScore });

  } catch (error: any) {
    console.error("Error in grading API:", error);
    return NextResponse.json({ error: error?.message || 'Internal Server Error' }, { status: 500 });
  }
}

export const POST = withAuthorizedRequest(handlePost, {"identityField": undefined, "teacher": true, "resource": "submission"});

import { scrubPII } from "@/lib/ai/utils";
import { withAuthorizedRequest } from "@/lib/auth-verify";
import { NextRequest, NextResponse } from 'next/server';
import { adminDb, adminFieldWithValue } from '@/lib/firebase-admin';
import { checkBudget, recordUsage } from '@/lib/usage-limit';
import { getNotebookAssistantResponse } from "@/lib/ai/notebook";
import { checkRateLimit } from '@/lib/rate-limit';

async function handlePost(req: NextRequest) {
  if (!adminDb) {
    return NextResponse.json({ error: 'Database not initialized' }, { status: 500 });
  }

  try {
    const { messages, notebookContent, studentId } = await req.json();

    if (!messages || !studentId) {
      return NextResponse.json({ error: 'Missing required parameters' }, { status: 400 });
    }

    // 1. Check Rate Limit
    const rateLimitCheck = await checkRateLimit(req, studentId, "notebook", { windowMs: 60000, maxRequests: 20 });
    if (!rateLimitCheck.allowed) {
      return NextResponse.json({ error: rateLimitCheck.error }, { status: 429 });
    }

    // 1. Resolve Organization for budget
    const studentDoc = await adminDb.collection("users").doc(studentId).get();
    if (!studentDoc.exists) {
        return NextResponse.json({ error: "Student profile not found" }, { status: 404 });
    }
    const studentData = studentDoc.data();
    let organizationId = studentData?.organizationId;

    // Fallback: students may not have organizationId directly — inherit from teacher
    if (!organizationId && studentData?.teacherId) {
      const teacherDoc = await adminDb.collection("users").doc(studentData.teacherId).get();
      organizationId = teacherDoc.data()?.organizationId;
    }

    if (!organizationId) {
        return NextResponse.json({ error: "You must be enrolled in an active Scorpio Network to use notebook AI features." }, { status: 403 });
    }

    // 2. Check Notebook Budget
    const orgRef = adminDb.collection("organizations").doc(organizationId);
    const orgSnap = await orgRef.get();
    const orgData = orgSnap.data();

    const notebookLimit = orgData?.notebookLimit || 50;
    const notebookUsage = orgData?.notebookUsageCurrent || 0;

    if (notebookUsage >= notebookLimit) {
        return NextResponse.json({ error: "The monthly notebook AI limit for your network has been reached." }, { status: 403 });
    }

    const budgetCheck = await checkBudget(organizationId, "notebook", studentId);
    if (budgetCheck.allowed) {
        // 3. Generate AI Response using centralized gemini helper
        const result = await getNotebookAssistantResponse(messages.map((m: { role: "user" | "assistant"; content: string }) => ({ ...m, content: scrubPII(m.content, [studentData?.displayName || ""]) })), scrubPII(notebookContent, [studentData?.displayName || ""]));
        const responseText = result.content;

        // 4. Record Usage and Increment Notebook Count
        if (result.usage) {
            await recordUsage(
              organizationId, 
              "notebook", 
              result.usage.inputTokens, 
              result.usage.outputTokens,
              studentId
            );
        }

        await orgRef.update({
            notebookUsageCurrent: adminFieldWithValue.increment(1)
        });

        return NextResponse.json({ content: responseText });
    }

    return NextResponse.json({ error: budgetCheck.error }, { status: 403 });

  } catch (error: any) {
    console.error('Notebook Copilot API Error:', error);
    return NextResponse.json({ 
      error: error?.message || 'Digital resonance failure. Copilot is offline.' 
    }, { status: 500 });
  }
}

export const POST = withAuthorizedRequest(handlePost, {"identityField": "studentId", "teacher": false});

import { withAuthorizedRequest } from "@/lib/auth-verify";
import { NextRequest, NextResponse } from "next/server";
import { adminDb, adminFieldWithValue } from "@/lib/firebase-admin";
import { generateStudentPortfolio } from "@/lib/ai/network";
import { checkBudget, recordUsage } from "@/lib/usage-limit";



async function handlePost(req: NextRequest) {
  try {
    const { teacherId, studentId, organizationId } = await req.json();

    if (!teacherId || !studentId || !organizationId) {
      return NextResponse.json({ error: "Missing required fields" }, { status: 400 });
    }

    if (!adminDb) {
      return NextResponse.json({ error: "Service unavailable" }, { status: 503 });
    }

    // 1. Verify Teacher and Organization
    const teacherDoc = await adminDb.collection("users").doc(teacherId).get();
    if (!teacherDoc.exists || teacherDoc.data()?.role !== "teacher") {
      return NextResponse.json({ error: "Unauthorized: Invalid teacher profile" }, { status: 403 });
    }

    if (teacherDoc.data()?.organizationId !== organizationId) {
      return NextResponse.json({ error: "Unauthorized: Teacher not in network" }, { status: 403 });
    }

    // 1.1 Check Budget
    const budgetCheck = await checkBudget(organizationId, "portfolio");
    if (!budgetCheck.allowed) {
      return NextResponse.json({ error: budgetCheck.error }, { status: 403 });
    }


    // 2. Fetch Student Name and Verification
    const studentDoc = await adminDb.collection("users").doc(studentId).get();
    if (!studentDoc.exists || studentDoc.data()?.role !== "student") {
      return NextResponse.json({ error: "Student not found" }, { status: 404 });
    }
    const studentData = studentDoc.data()!;
    const studentName = studentData.displayName || studentData.name || "Unknown Student";

    // Build chat history from past sessions
    // Realistically, we fetch the last X sessions (e.g. max 5 recent sessions to save tokens)
    const sessionsSnapshot = await adminDb.collection("tutor_sessions")
      .where("studentId", "==", studentId)
      .orderBy("updatedAt", "desc")
      .limit(5)
      .get();

    let allChatHistory: { role: "user" | "assistant"; content: string }[] = [];

    // We want chronological order inside the prompt, so reverse the sessions to have oldest of the recent 5 first
    const sessions = sessionsSnapshot.docs.reverse();

    for (const sessionDoc of sessions) {
      const messages = sessionDoc.data().messages || [];
      const formattedMessages = messages.map((m: any) => ({
        role: m.role as "user" | "assistant",
        content: m.content
      }));
      allChatHistory = allChatHistory.concat(formattedMessages);
    }

    // 3. Generate Portfolio via Gemini
    // Limit total messages to top ~50 most recent from those 5 sessions if it's too large, but 5 sessions is usually okay.
    if (allChatHistory.length > 50) {
      allChatHistory = allChatHistory.slice(-50); // Keep only last 50 messages to save context limit
    }

    const result = await generateStudentPortfolio(studentName, allChatHistory);
    const portfolio = result.portfolio;
    const usage = result.usage;

    // 3.1 Record Usage
    if (usage) {
      await recordUsage(
        organizationId,
        "portfolio",
        usage.inputTokens,
        usage.outputTokens,
        teacherId // Recorded against the teacher who initiated the generation
      );
    }

    const portfolioData = {
      studentId,
      organizationId,
      teacherId,
      lastUpdated: adminFieldWithValue.serverTimestamp(),
      strengths: portfolio.strengths,
      weaknesses: portfolio.weaknesses,
      masteryLevel: portfolio.masteryLevel,
      aiSummary: portfolio.aiSummary
    };

    // 4. Save to Firestore portfolios collection
    await adminDb.collection("portfolios").doc(studentId).set(portfolioData, { merge: true });

    return NextResponse.json({ 
      success: true, 
      portfolio: {
        ...portfolioData,
        lastUpdated: new Date() // Send client-friendly date format
      } 
    });
  } catch (error: any) {
    console.error("Student Portfolio Generation Error:", error);
    return NextResponse.json({ error: error.message || "Internal server error" }, { status: 500 });
  }
}

