"use client";

import { useEffect, useState } from "react";
import Link from "next/link";
import { collection, getDocs, query, where, doc, getDoc } from "firebase/firestore";
import { db } from "@/lib/firebase";
import { useAuth } from "@/contexts/auth-context";
import { WorkspaceHeader } from "@/components/ui/workspace";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { DropdownMenu, DropdownMenuTrigger, DropdownMenuContent, DropdownMenuItem } from "@/components/ui/dropdown-menu";
import { ChevronDown } from "lucide-react";

interface Assignment {
  id: string;
  title: string;
  description: string;
  dueDate: Date;
  questions?: unknown[];
  courseId: string;
  teacherId: string;
}

export default function StudentAssignmentsPage() {
  const { user, profile } = useAuth();
  const [assignments, setAssignments] = useState<Assignment[]>([]);
  const [submissions, setSubmissions] = useState<Set<string>>(new Set());
  const [loading, setLoading] = useState(true);
  const [filter, setFilter] = useState<string>("all");
  const [sort, setSort] = useState<string>("dueDateAsc");

  useEffect(() => {
    async function fetchData() {
      if (!user) return;
      try {
        // Source of truth: Use unified profile if available, otherwise fallback to legacy students collection
        let teacherId = profile?.teacherId;
        let courseId = profile?.courseId;

        if (!courseId || !teacherId) {
          try {
            const studentDoc = await getDoc(doc(db, "students", user.uid));
            if (studentDoc.exists()) {
              const studentData = studentDoc.data();
              teacherId = teacherId || studentData.teacherId;
              courseId = courseId || studentData.courseId;
            }
          } catch (e) { console.error("Could not fetch legacy student profile", e); }
        }



        let data: Assignment[] = [];
        if (courseId) {
          // New system: filter by specific course
          const assignmentsSnap = await getDocs(
            query(collection(db, "assignments"), where("answerKeySeparated", "==", true), where("courseId", "==", courseId))
          );
          data = assignmentsSnap.docs.map((doc) => ({
            id: doc.id,
            ...doc.data(),
            dueDate: doc.data().dueDate?.toDate?.() || (doc.data().dueDate ? new Date(doc.data().dueDate) : new Date()),
          })) as Assignment[];
        } else if (teacherId) {
          // Fallback for legacy connections
          const assignmentsSnap = await getDocs(
            query(collection(db, "assignments"), where("answerKeySeparated", "==", true), where("teacherId", "==", teacherId), where("courseId", "==", null))
          );
          data = assignmentsSnap.docs.map((doc) => ({
            id: doc.id,
            ...doc.data(),
            dueDate: doc.data().dueDate?.toDate?.() || new Date(doc.data().dueDate),
          })) as Assignment[];
        }
        setAssignments(data);

        const submissionsSnap = await getDocs(
          query(collection(db, "submissions"), where("studentId", "==", user.uid))
        );
        const submittedIds = new Set(
          submissionsSnap.docs
            .filter(doc => doc.data().status !== 'draft')
            .map((doc) => doc.data().assignmentId)
        );
        setSubmissions(submittedIds);
      } catch (error) {
        console.error("Error fetching assignments:", error);
      } finally {
        setLoading(false);
      }
    }
    fetchData();
  }, [user, profile]);

  const isPastDue = (date: Date) => new Date(date) < new Date();

  function formatDueDate(dueDate: Date | null | undefined, isSubmitted: boolean) {
    if (!dueDate || isNaN(new Date(dueDate).getTime())) {
      return {
        formattedDate: "No due date",
        relativeText: isSubmitted ? "Submitted" : "Open",
        urgency: "normal" as const,
      };
    }

    const now = new Date();
    const due = new Date(dueDate);

    // Strip time for day comparison
    const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
    const dueDay = new Date(due.getFullYear(), due.getMonth(), due.getDate());
    const diffDays = Math.round((dueDay.getTime() - today.getTime()) / (1000 * 60 * 60 * 24));

    const formattedDate = due.toLocaleDateString(undefined, {
      weekday: "short",
      month: "short",
      day: "numeric",
      year: due.getFullYear() !== now.getFullYear() ? "numeric" : undefined,
    });

    let relativeText = "";
    let urgency: "normal" | "urgent" | "past" | "submitted" = "normal";

    if (isSubmitted) {
      relativeText = "Submitted";
      urgency = "submitted";
    } else if (diffDays < 0) {
      const daysAgo = Math.abs(diffDays);
      relativeText = daysAgo === 1 ? "1 day overdue" : `${daysAgo} days overdue`;
      urgency = "past";
    } else if (diffDays === 0) {
      relativeText = "Due today";
      urgency = "urgent";
    } else if (diffDays === 1) {
      relativeText = "Due tomorrow";
      urgency = "urgent";
    } else if (diffDays <= 7) {
      relativeText = `In ${diffDays} days`;
      urgency = "normal";
    } else {
      relativeText = `${Math.ceil(diffDays / 7)} weeks left`;
      urgency = "normal";
    }

    return { formattedDate, relativeText, urgency };
  }

  // Filtering
  let filteredAssignments = assignments.filter((assignment) => {
    const isSubmitted = submissions.has(assignment.id);
    const pastDue = isPastDue(assignment.dueDate);
    if (filter === "submitted") return isSubmitted;
    if (filter === "pending") return !isSubmitted && !pastDue;
    if (filter === "pastDue") return !isSubmitted && pastDue;
    return true;
  });

  const counts = {
    all: assignments.length,
    pending: assignments.filter((a) => !submissions.has(a.id) && !isPastDue(a.dueDate)).length,
    submitted: assignments.filter((a) => submissions.has(a.id)).length,
    pastDue: assignments.filter((a) => !submissions.has(a.id) && isPastDue(a.dueDate)).length,
  };

  // Sorting
  filteredAssignments = filteredAssignments.sort((a, b) => {
    if (sort === "dueDateAsc") {
      return new Date(a.dueDate).getTime() - new Date(b.dueDate).getTime();
    } else if (sort === "dueDateDesc") {
      return new Date(b.dueDate).getTime() - new Date(a.dueDate).getTime();
    } else if (sort === "titleAsc") {
      return a.title.localeCompare(b.title);
    } else if (sort === "titleDesc") {
      return b.title.localeCompare(a.title);
    }
    return 0;
  });

  return (
    <div className="space-y-6">
      <WorkspaceHeader title="Assignments" description="Open coursework and check what’s due." />
      <div className="flex flex-wrap gap-2 items-center">
        <DropdownMenu>
          <DropdownMenuTrigger asChild>
            <Button variant="outline" size="sm" className="h-9">
              Status: {(() => {
                if (filter === "all") return `All (${counts.all})`;
                if (filter === "submitted") return `Submitted (${counts.submitted})`;
                if (filter === "pending") return `Pending (${counts.pending})`;
                if (filter === "pastDue") return `Past Due (${counts.pastDue})`;
                return "All";
              })()} <ChevronDown className="w-3.5 h-3.5 ml-1.5 opacity-60" />
            </Button>
          </DropdownMenuTrigger>
          <DropdownMenuContent align="start">
            <DropdownMenuItem onSelect={() => setFilter("all")}>
              All ({counts.all})
            </DropdownMenuItem>
            <DropdownMenuItem onSelect={() => setFilter("pending")}>
              Pending ({counts.pending})
            </DropdownMenuItem>
            <DropdownMenuItem onSelect={() => setFilter("submitted")}>
              Submitted ({counts.submitted})
            </DropdownMenuItem>
            <DropdownMenuItem onSelect={() => setFilter("pastDue")}>
              Past Due ({counts.pastDue})
            </DropdownMenuItem>
          </DropdownMenuContent>
        </DropdownMenu>

        <DropdownMenu>
          <DropdownMenuTrigger asChild>
            <Button variant="outline" size="sm" className="h-9">
              Sort by: {(() => {
                if (sort === "dueDateAsc") return "Due Date (Earliest)";
                if (sort === "dueDateDesc") return "Due Date (Latest)";
                if (sort === "titleAsc") return "Title (A–Z)";
                if (sort === "titleDesc") return "Title (Z–A)";
                return "Due Date (Earliest)";
              })()} <ChevronDown className="w-3.5 h-3.5 ml-1.5 opacity-60" />
            </Button>
          </DropdownMenuTrigger>
          <DropdownMenuContent align="start">
            <DropdownMenuItem onSelect={() => setSort("dueDateAsc")}>Due Date (Earliest)</DropdownMenuItem>
            <DropdownMenuItem onSelect={() => setSort("dueDateDesc")}>Due Date (Latest)</DropdownMenuItem>
            <DropdownMenuItem onSelect={() => setSort("titleAsc")}>Title (A–Z)</DropdownMenuItem>
            <DropdownMenuItem onSelect={() => setSort("titleDesc")}>Title (Z–A)</DropdownMenuItem>
          </DropdownMenuContent>
        </DropdownMenu>
      </div>

      <div className="overflow-hidden rounded-xl border border-border bg-card">
        <div className="flex items-center justify-between border-b border-border/80 bg-muted/40 px-5 py-3">
          <span className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">
            Coursework ({filteredAssignments.length})
          </span>
          <span className="text-xs text-muted-foreground">
            {sort === "dueDateAsc"
              ? "Earliest due first"
              : sort === "dueDateDesc"
              ? "Latest due first"
              : sort === "titleAsc"
              ? "Alphabetical (A–Z)"
              : "Alphabetical (Z–A)"}
          </span>
        </div>

        {loading ? (
          <p role="status" className="p-6 text-sm text-muted-foreground">Loading assignments…</p>
        ) : filteredAssignments.length === 0 ? (
          <p className="p-6 text-sm text-muted-foreground">No assignments match this view.</p>
        ) : (
          <ul className="divide-y divide-border">
            {filteredAssignments.map((assignment) => {
              const isSubmitted = submissions.has(assignment.id);
              const pastDue = !isSubmitted && isPastDue(assignment.dueDate);
              const dateInfo = formatDueDate(assignment.dueDate, isSubmitted);

              return (
                <li
                  key={assignment.id}
                  className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 px-5 py-4 transition-colors hover:bg-muted/20"
                >
                  <div className="min-w-0 flex-1 space-y-1">
                    <div className="flex flex-wrap items-center gap-2">
                      <h2 className="break-words text-sm font-semibold text-foreground">
                        {assignment.title}
                      </h2>
                      {isSubmitted && (
                        <Badge variant="secondary" className="text-[10px] h-4.5 px-1.5 font-normal">
                          Submitted
                        </Badge>
                      )}
                    </div>
                    {assignment.description && (
                      <p className="line-clamp-2 text-xs leading-relaxed text-muted-foreground">
                        {assignment.description}
                      </p>
                    )}
                    <p className="text-xs text-muted-foreground/80">
                      {assignment.questions?.length || 0}{" "}
                      {assignment.questions?.length === 1 ? "question" : "questions"}
                    </p>
                  </div>

                  <div className="flex items-center justify-between sm:justify-end gap-5 shrink-0 border-t sm:border-t-0 pt-2 sm:pt-0 border-border/60">
                    <div className="text-left sm:text-right space-y-0.5 min-w-[110px]">
                      <p className="text-[10px] font-medium uppercase tracking-wider text-muted-foreground">
                        Due Date
                      </p>
                      <p className="text-sm font-semibold tabular-nums text-foreground">
                        {dateInfo.formattedDate}
                      </p>
                      <p
                        className={`text-xs tabular-nums ${
                          dateInfo.urgency === "urgent"
                            ? "font-medium text-primary"
                            : dateInfo.urgency === "past"
                            ? "font-medium text-destructive"
                            : "text-muted-foreground"
                        }`}
                      >
                        {dateInfo.relativeText}
                      </p>
                    </div>

                    <Button
                      asChild
                      size="sm"
                      variant={isSubmitted ? "outline" : "default"}
                      className="shrink-0 h-9 px-4 text-xs font-medium"
                    >
                      <Link
                        href={`/student/assignment-view?id=${assignment.id}`}
                        aria-label={`${isSubmitted ? "View" : "Start"} ${assignment.title}`}
                      >
                        {isSubmitted ? "View" : "Start"}
                      </Link>
                    </Button>
                  </div>
                </li>
              );
            })}
          </ul>
        )}
      </div>
    </div>
  );
}

"use client";

import { useEffect, useState, useMemo } from "react";
import { collection, query, where, getDocs, getDoc, doc } from "firebase/firestore";
import { db } from "@/lib/firebase";
import { useAuth } from "@/contexts/auth-context";
import { Card, CardContent } from "@/components/ui/card";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { ChevronRight } from "lucide-react";
import { LoadingSpinner } from "@/components/ui/loading-spinner";
import { WorkspaceHeader, WorkspaceSummary } from "@/components/ui/workspace";
import { MarkdownRenderer } from "@/components/markdown-renderer";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";

interface Submission {
  id: string;
  assignmentId: string;
  assignmentTitle: string;
  submittedAt: Date | null;
  score: number | null;
  graded: boolean;
  feedback?: string;
  answers?: any;
  status?: string;
}

export default function StudentGradesPage() {
  const { user, profile } = useAuth();
  const [submissions, setSubmissions] = useState<Submission[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    async function fetchGrades() {
      if (!user) return;

      try {
        let studentTeacherId = profile?.teacherId;
        let studentCourseId = profile?.courseId;

        if (!studentTeacherId || !studentCourseId) {
          try {
            const studentDoc = await getDoc(doc(db, "students", user.uid));
            if (studentDoc.exists()) {
              const studentData = studentDoc.data();
              studentTeacherId = studentTeacherId || studentData.teacherId;
              studentCourseId = studentCourseId || studentData.courseId;
            }
          } catch (e) {
            console.error("Could not fetch legacy student profile", e);
          }
        }

        if (studentTeacherId && !studentCourseId) {
          const codeMatch = await getDocs(
            query(collection(db, "courses"), where("code", "==", studentTeacherId.trim()))
          );
          if (!codeMatch.empty) {
            const courseDoc = codeMatch.docs[0];
            const courseData = courseDoc.data();
            studentCourseId = courseDoc.id;
            studentTeacherId = courseData.teacherId;
          }
        }

        const q = query(collection(db, "submissions"), where("studentId", "==", user.uid));
        const snapshot = await getDocs(q);

        const submissionsData: (Submission | null)[] = await Promise.all(
          snapshot.docs.map(async (docSnapshot) => {
            const data = docSnapshot.data();

            let assignmentTitle = "Unknown Assignment";
            let assignmentExists = false;
            let assignmentTeacherId = null;
            let assignmentCourseId = null;

            if (data.assignmentId) {
              const assignmentDoc = await getDoc(doc(db, "assignments", data.assignmentId));
              if (assignmentDoc.exists()) {
                const assignData = assignmentDoc.data();
                assignmentTitle = assignData.title;
                assignmentTeacherId = assignData.teacherId;
                assignmentCourseId = assignData.courseId;
                assignmentExists = true;
              }
            }

            if (!assignmentExists) return null;

            if (studentCourseId) {
              if (assignmentCourseId !== studentCourseId) return null;
            } else if (studentTeacherId && assignmentTeacherId && studentTeacherId !== assignmentTeacherId) {
              return null;
            }

            return {
              id: docSnapshot.id,
              assignmentId: data.assignmentId,
              assignmentTitle,
              submittedAt: data.submittedAt?.toDate?.() || (data.submittedAt ? new Date(data.submittedAt) : null),
              score: typeof data.score === "number" ? data.score : null,
              graded: data.graded,
              feedback: data.feedback,
              answers: data.answers,
              status: data.status || (data.graded ? "graded" : "submitted"),
            } satisfies Submission;
          })
        );

        const filteredSubmissions = submissionsData.filter(
          (s): s is Submission => s !== null && s.status !== "draft"
        );

        filteredSubmissions.sort((a, b) => {
          const dateA = a.submittedAt?.getTime() || 0;
          const dateB = b.submittedAt?.getTime() || 0;
          return dateB - dateA; // Sort newest first for the history list
        });

        setSubmissions(filteredSubmissions);
      } catch (error) {
        console.error("Error fetching grades:", error);
      } finally {
        setLoading(false);
      }
    }

    fetchGrades();
  }, [user, profile]);

  const stats = useMemo(() => {
    const graded = submissions.filter((s) => s.graded && s.score !== null);
    const scores = graded.map((s) => s.score as number);
    const average = scores.length > 0 ? scores.reduce((a, b) => a + b, 0) / scores.length : 0;
    const highest = scores.length > 0 ? Math.max(...scores) : 0;
    const total = submissions.length;
    const pending = submissions.filter((s) => !s.graded).length;

    return { average, highest, total, pending, hasScores: scores.length > 0 };
  }, [submissions]);

  if (loading) {
    return <LoadingSpinner fullPage />;
  }

  return (
    <div className="space-y-6">
      <WorkspaceHeader title="Grades" description="See your scores and review instructor feedback." />
      <WorkspaceSummary label="Grade summary" items={[
        { label: "Average", value: stats.hasScores ? `${stats.average.toFixed(1)}%` : "—" },
        { label: "Highest score", value: stats.hasScores ? `${stats.highest}%` : "—" },
        { label: "Graded", value: stats.total - stats.pending },
        { label: "Awaiting grade", value: stats.pending },
      ]} />

      <section aria-labelledby="grade-history" className="space-y-3">
        <h2 id="grade-history" className="text-lg font-semibold">Assignment results</h2>
        <Card className="overflow-hidden py-0 shadow-none">
          <CardContent className="p-0">
            {submissions.length === 0 ? (
              <p className="p-6 text-sm text-muted-foreground">Your scores will appear here after you submit coursework.</p>
            ) : (
              <Table aria-labelledby="grade-history">
                <TableHeader className="bg-muted/40">
                  <TableRow className="hover:bg-transparent">
                    <TableHead className="px-4">Assignment</TableHead>
                    <TableHead className="text-center">Status</TableHead>
                    <TableHead className="text-center">Score</TableHead>
                    <TableHead className="text-right px-4">Actions</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {submissions.map((submission) => (
                    <TableRow key={submission.id}>
                      <TableCell className="px-4 py-3">
                        <div className="whitespace-normal break-words font-medium">{submission.assignmentTitle}</div>
                        <div className="text-xs text-muted-foreground">
                          {submission.submittedAt ? submission.submittedAt.toLocaleDateString(undefined, {
                            month: 'short',
                            day: 'numeric',
                            year: 'numeric'
                          }) : "N/A"}
                        </div>
                      </TableCell>
                      <TableCell className="py-3 text-center">
                        {submission.graded ? (
                          <Badge variant="secondary">
                            Graded
                          </Badge>
                        ) : (
                          <Badge variant="outline">
                            Pending
                          </Badge>
                        )}
                      </TableCell>
                      <TableCell className="py-3 text-center">
                        <span className="font-medium tabular-nums">
                          {submission.graded && submission.score !== null ? `${submission.score}%` : "—"}
                        </span>
                      </TableCell>
                      <TableCell className="text-right px-4 py-3">
                        <Dialog>
                          <DialogTrigger asChild>
                            <Button
                              variant="ghost"
                              size="sm"
                              aria-label={`View details for ${submission.assignmentTitle}`}
                            >
                              Details
                              <ChevronRight className="h-4 w-4 ml-1" />
                            </Button>
                          </DialogTrigger>
                          <DialogContent className="sm:max-w-3xl max-h-[90dvh] overflow-hidden flex flex-col gap-0 p-0">
                            <DialogHeader className="p-4 pr-12 sm:p-6 sm:pr-14 border-b border-border">
                              <div className="flex flex-wrap items-center justify-between gap-3">
                                <div>
                                  <DialogTitle className="break-words text-xl font-semibold tracking-tight">{submission.assignmentTitle}</DialogTitle>
                                  <DialogDescription className="text-sm font-medium mt-1">
                                    Submitted on {submission.submittedAt ? submission.submittedAt.toLocaleDateString(undefined, {
                                      weekday: 'long',
                                      year: 'numeric',
                                      month: 'long',
                                      day: 'numeric'
                                    }) : "N/A"}
                                  </DialogDescription>
                                </div>
                                <div className="text-right">
                                  <div className="text-xl font-semibold tabular-nums">
                                    {submission.graded && submission.score !== null ? `${submission.score}%` : "—"}
                                  </div>
                                  <div className="text-xs text-muted-foreground">Score</div>
                                </div>
                              </div>
                            </DialogHeader>

                            <div className="min-h-0 flex-1 overflow-y-auto p-4 sm:p-6">
                              {/* Graded Copy Section */}
                              {submission.graded && Array.isArray(submission.answers) && submission.answers.length > 0 ? (
                                <div className="space-y-6">
                                  {submission.answers.map((q: any, idx: number) => (
                                    <div
                                      key={q.questionId || idx}
                                      className="space-y-4 border-b border-border pb-5 last:border-0 last:pb-0"
                                    >
                                      <div className="flex items-start justify-between">
                                        <div className="flex items-center gap-3">
                                          <p className="text-sm font-semibold">
                                            Question {idx + 1}
                                          </p>
                                        </div>
                                        <Badge variant="secondary">
                                          Points: {typeof q.score === "number" ? q.score : "-"}
                                        </Badge>
                                      </div>

                                      <div className="break-words text-sm font-medium">
                                        <MarkdownRenderer noProse>
                                          {q.questionText}
                                        </MarkdownRenderer>
                                      </div>

                                      <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
                                        <div className="space-y-2">
                                          <p className="text-xs font-medium text-muted-foreground">
                                            Your Answer
                                          </p>
                                          <div className="break-words rounded-lg bg-muted/40 p-3 text-sm">
                                            {q.answer?.trim() ? (
                                              <MarkdownRenderer noProse>
                                                {q.answer}
                                              </MarkdownRenderer>
                                            ) : <span className="italic opacity-50">No answer provided</span>}
                                          </div>
                                        </div>

                                        {q.feedback?.trim() && (
                                          <div className="space-y-2">
                                            <p className="text-xs font-medium text-muted-foreground">
                                              Feedback
                                            </p>
                                            <div className="break-words rounded-lg bg-muted/40 p-3 text-sm">
                                              <MarkdownRenderer noProse>
                                                {q.feedback}
                                              </MarkdownRenderer>
                                            </div>
                                          </div>
                                        )}
                                      </div>
                                    </div>
                                  ))}
                                </div>
                              ) : (
                                <p className="text-sm text-muted-foreground">
                                  {submission.graded ? "No question-by-question feedback is available." : "This submission is awaiting a grade."}
                                </p>
                              )}
                            </div>
                          </DialogContent>
                        </Dialog>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            )}
          </CardContent>
        </Card>
      </section>
    </div>
  );
}

"use client";
import { authenticatedFetch } from "@/lib/authenticated-fetch";

import * as React from "react";
import { useState, useEffect, useRef } from "react";
import dynamic from "next/dynamic";
import { useAuth } from "@/contexts/auth-context";
import { db } from "@/lib/firebase";
import {
  doc,
  getDoc,
  setDoc,
  onSnapshot,
  updateDoc,
  serverTimestamp,
  collection,
  query,
  where,
  deleteDoc,
  increment
} from "firebase/firestore";
import { WorkspaceHeader } from "@/components/ui/workspace";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { ScrollArea } from "@/components/ui/scroll-area";
import { MarkdownRenderer } from "@/components/markdown-renderer";
import {
  Send,
  Loader2,
  Save,
  PenLine,
  Eye,
  Cpu,
  Trash2,
  Maximize2,
  BookMarked,
  Lock,
  Plus,
  MoreVertical,
  X,
  Crown,
  ZoomIn,
  ZoomOut,
  RotateCcw,
  Minimize2
} from "lucide-react";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger
} from "@/components/ui/dropdown-menu";

interface Notebook {
  id: string;
  title: string;
  content: string;
  studentId: string;
  createdAt: any;
  updatedAt: any;
}
import { Badge } from "@/components/ui/badge";
import { cn } from "@/lib/utils";
import { toast } from "sonner";
import TurndownService from "turndown";
import Showdown from "showdown";
import { ConfirmDialog } from "@/components/ui/confirm-dialog";
import { RaiseLogo } from "@/components/ui/raise-logo";

const turndown = new TurndownService();
const converter = new Showdown.Converter();

// Lazy load RichTextEditor to avoid SSR hydration issues
const RichTextEditor = dynamic(() => import("@/components/rich-text-editor").then(mod => mod.RichTextEditor), {
  ssr: false,
  loading: () => <div className="h-full w-full bg-muted animate-pulse flex items-center justify-center text-[10px] font-bold text-muted-foreground">Loading editor…</div>
});

interface Message {
  role: 'user' | 'assistant';
  content: string;
}

export default function NotebookPage() {
  const { user } = useAuth();
  const [notebooks, setNotebooks] = useState<Notebook[]>([]);
  const [activeNotebookId, setActiveNotebookId] = useState<string | null>(null);
  const [content, setContent] = useState("");
  const [title, setTitle] = useState("Untitled Notebook");
  const [isEditing, setIsEditing] = useState(true);
  const [editorMode, setEditorMode] = useState<'markdown' | 'rich-text'>('rich-text');
  const [notebookToDelete, setNotebookToDelete] = useState<string | null>(null);
  const [messages, setMessages] = useState<Message[]>([]);
  const [inputValue, setInputValue] = useState("");
  const [isLoading, setIsLoading] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [lastSavedAt, setLastSavedAt] = useState<Date | null>(null);
  const [hasUnsavedChanges, setHasUnsavedChanges] = useState(false);
  const [isLocked, setIsLocked] = useState(false);
  const [orgData, setOrgData] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [studentUsage, setStudentUsage] = useState<number>(0);
  const [showCopilot, setShowCopilot] = useState(false);
  const [isFullScreen, setIsFullScreen] = useState(false);
  const [zoomLevel, setZoomLevel] = useState(100);
  const [editingTitleId, setEditingTitleId] = useState<string | null>(null);

  // Use onSnapshot for real-time usage tracking from the user document
  useEffect(() => {
    if (!user) return;
    const unsubscribe = onSnapshot(doc(db, "users", user.uid), (doc) => {
      if (doc.exists()) {
        setStudentUsage(doc.data().aiUsageCount || 0);
      }
    });
    return () => unsubscribe();
  }, [user]);

  // AI is disabled IF:
  // 1. Organization has exhausted its budget (aiUsageCurrent >= aiBudgetLimit, with safety for 0 limits)
  // 2. Student has reached their personal monthly interaction limit
  const isAiDisabled =
    (orgData?.aiBudgetLimit > 0 && (orgData?.aiUsageCurrent || 0) >= (orgData?.aiBudgetLimit || 0)) ||
    (orgData?.aiNotebookLimitPerStudent > 0 && studentUsage >= (orgData?.aiNotebookLimitPerStudent || 0));

  // Helper to get HTML from Markdown
  const getHtml = (md: string) => converter.makeHtml(md);
  // Helper to get Markdown from HTML
  const getMarkdown = (html: string) => turndown.turndown(html);

  const scrollRef = useRef<HTMLDivElement>(null);
  const helpPanelRef = useRef<HTMLElement>(null);

  useEffect(() => {
    if (showCopilot && window.matchMedia("(max-width: 1279px)").matches) {
      helpPanelRef.current?.scrollIntoView({ block: "nearest" });
    }
  }, [showCopilot]);

  // Fetch List of Notebooks & Org Settings
  useEffect(() => {
    if (!user) return;

    // 1. Fetch Organization Data first for limits
    async function fetchOrgSettings() {
      try {
        const userDoc = await getDoc(doc(db, "users", user!.uid));
        const userData = userDoc.data();
        const orgId = userData?.organizationId;

        if (orgId) {
          // Use onSnapshot for real-time subscription status updates
          const unsubscribeOrg = onSnapshot(doc(db, "organizations", orgId), (orgSnap) => {
            if (orgSnap.exists()) {
              const data = orgSnap.data();
              setOrgData(data);
              if (data?.notebookLimit === 0) setIsLocked(true);
            }
          });
          return unsubscribeOrg;
        }
      } catch (err) {
        console.error("Access config failed:", err);
      }
    }

    const orgPromise = fetchOrgSettings();
    let orgUnsubscribe: (() => void) | undefined;
    orgPromise.then(unsub => { orgUnsubscribe = unsub; });

    // 2. Load Notebook List
    const q = query(collection(db, "notebooks"), where("studentId", "==", user.uid));
    const unsubscribe = onSnapshot(q, (snapshot) => {
      const handleSnapshot = async () => {
        let list = snapshot.docs.map(d => ({ id: d.id, ...d.data() } as Notebook));

        // Migration: Check if a notebook existed at notebooks/{uid} (the old structure)
        if (list.length === 0) {
          try {
            const oldRef = doc(db, "notebooks", user.uid);
            const oldSnap = await getDoc(oldRef);

            if (oldSnap.exists()) {
              const oldData = oldSnap.data();
              if (!oldData.studentId) {
                const newRef = doc(collection(db, "notebooks"));
                await setDoc(newRef, {
                  title: "Initial Notebook",
                  content: oldData.content || "",
                  studentId: user.uid,
                  createdAt: oldData.createdAt || serverTimestamp(),
                  updatedAt: oldData.updatedAt || serverTimestamp()
                });
                await updateDoc(oldRef, { studentId: user.uid, title: "Initial Notebook Migration" });
                return; // Re-fire listener
              }
            } else {
              // New user - create one
              const newRef = doc(collection(db, "notebooks"));
              await setDoc(newRef, {
                title: "My Research Notebook",
                content: "# Welcome\n\nCapture your thoughts here.",
                studentId: user.uid,
                createdAt: serverTimestamp(),
                updatedAt: serverTimestamp()
              });
              return; // Re-fire listener
            }
          } catch (err) {
            console.error("Migration/Setup error:", err);
            // Fallback: clear loading so user doesn't get stuck even if setup fails
            setLoading(false);
          }
        } else {
          setNotebooks(list);

          if (!activeNotebookId && list.length > 0) {
            setActiveNotebookId(list[0].id);
          }

          setLoading(false);
        }
      };

      handleSnapshot();
    }, (error) => {
      console.error("Snapshot error:", error);
      setLoading(false);
      toast.error("Cloud synchronization error.");
    });

    return () => {
      unsubscribe();
      if (orgUnsubscribe) orgUnsubscribe();
    };
  }, [user]);

  // Sync content and message history with active notebook
  useEffect(() => {
    if (!activeNotebookId || !user) return;

    const docRef = doc(db, "notebooks", activeNotebookId);
    const unsubscribe = onSnapshot(docRef, (docSnap) => {
      if (docSnap.exists()) {
        const data = docSnap.data();
        if (!hasUnsavedChanges) {
          setContent(data.content || "");
          setTitle(data.title || "Untitled");
          setLastSavedAt(data.updatedAt?.toDate() || null);
          // Load chat history from the notebook document
          if (data.messages && Array.isArray(data.messages)) {
            setMessages(data.messages);
          } else {
            setMessages([]);
          }
        }
      }
    });

    return () => unsubscribe();
  }, [activeNotebookId, hasUnsavedChanges]);

  // Auto-save logic
  useEffect(() => {
    if (!hasUnsavedChanges) return;

    const timeoutId = setTimeout(async () => {
      await saveNotebook();
    }, 3000);

    return () => clearTimeout(timeoutId);
  }, [hasUnsavedChanges, content, title]);

  const saveNotebook = async () => {
    if (!user || !activeNotebookId || !hasUnsavedChanges) return;

    setIsSaving(true);
    try {
      const docRef = doc(db, "notebooks", activeNotebookId);
      await updateDoc(docRef, {
        content: content,
        title: title,
        updatedAt: serverTimestamp()
      });
      setLastSavedAt(new Date());
      setHasUnsavedChanges(false);
    } catch (error) {
      console.error("Save failed:", error);
      toast.error("Sync failed.");
    } finally {
      setIsSaving(false);
    }
  };

  const createNewNotebook = async () => {
    if (!user || !orgData) return;

    const limit = orgData?.notebookLimitPerStudent || 1;
    if (notebooks.length >= limit) {
      toast.error(`Allowance exceeded. Limited to ${limit} notebooks.`);
      return;
    }

    try {
      const newRef = doc(collection(db, "notebooks"));
      await setDoc(newRef, {
        title: "New Notebook",
        content: "",
        studentId: user.uid,
        createdAt: serverTimestamp(),
        updatedAt: serverTimestamp()
      });
      setActiveNotebookId(newRef.id);
      toast.success("New notebook initialized.");
    } catch (err) {
      toast.error("Notebook creation failed.");
    }
  };

  const deleteNotebook = async (id: string) => {
    if (!id || notebooks.length <= 1) {
      toast.error("At least one notebook is required.");
      return;
    }

    setNotebookToDelete(id);
  };

  const handleConfirmDelete = async () => {
    if (!notebookToDelete) return;

    try {
      await deleteDoc(doc(db, "notebooks", notebookToDelete));
      if (activeNotebookId === notebookToDelete) {
        const remaining = notebooks.filter(n => n.id !== notebookToDelete);
        setActiveNotebookId(remaining[0]?.id || null);
      }
      toast.success("Notebook erased.");
    } catch (err) {
      toast.error("Deletion failed.");
    } finally {
      setNotebookToDelete(null);
    }
  };

  const handleMarkdownChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    const val = e.target.value;
    if (val !== content) {
      setContent(val);
      setHasUnsavedChanges(true);
    }
  };

  const handleRichTextChange = (html: string) => {
    const md = getMarkdown(html);
    if (md !== content) {
      setContent(md);
      setHasUnsavedChanges(true);
    }
  };

  const handleSendMessage = async () => {
    if (!inputValue.trim() || !user || isLoading) return;

    if (isAiDisabled) {
      toast.error(
        studentUsage >= (orgData?.aiNotebookLimitPerStudent || 0) && (orgData?.aiNotebookLimitPerStudent || 0) > 0
          ? "Monthly interaction limit reached. Contact your instructor to increase your quota."
          : "Network monthly AI budget reached."
      );
      return;
    }

    const userMessage: Message = { role: 'user', content: inputValue };
    const newMessages = [...messages, userMessage];
    setMessages(newMessages);
    setInputValue("");
    setIsLoading(true);

    // Also persist users's message to notebook right away
    if (activeNotebookId) {
      updateDoc(doc(db, "notebooks", activeNotebookId), {
        messages: newMessages,
        updatedAt: serverTimestamp()
      });
    }

    try {
      const response = await authenticatedFetch('/api/notebook/chat', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          messages: newMessages,
          notebookContent: content,
          studentId: user.uid
        })
      });

      const data = await response.json();

      if (data.error) {
        toast.error(data.error);
        return;
      }

      setMessages(prev => {
        const updatedMessages = [...prev, { role: 'assistant' as const, content: data.content }];
        // Persist messages to the notebook document
        if (activeNotebookId) {
          const notebookRef = doc(db, "notebooks", activeNotebookId);
          updateDoc(notebookRef, {
            messages: updatedMessages,
            updatedAt: serverTimestamp()
          });
        }
        return updatedMessages;
      });

      // Persist usage count to Firestore
      if (user) {
        const userRef = doc(db, "users", user.uid);
        await updateDoc(userRef, {
          aiUsageCount: increment(1)
        });
      }
    } catch (error) {
      toast.error("Copilot connection severed.");
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isLoading]);

  if (isLocked) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[50dvh] space-y-6 text-center">
        <div className="p-6 bg-amber-50 dark:bg-amber-900/10 rounded-full">
          <Lock className="h-12 w-12 text-amber-500" />
        </div>
        <div className="max-w-md space-y-2">
          <h2 className="text-2xl font-black tracking-tight">Access Restricted</h2>
          <p className="text-sm text-muted-foreground font-medium leading-relaxed">
            Your instructor has not enabled Digital Notebook access for this network.
            Please contact your teacher to activate this researcher tool.
          </p>
        </div>
        <Button variant="outline" className="rounded-xl font-bold px-8 cursor-pointer" onClick={() => window.history.back()}>
          Return to Dashboard
        </Button>
      </div>
    );
  }

  return (
    <div className="space-y-5">

      {/* FULL SCREEN VIEWER OVERLAY */}
      {isFullScreen && !isEditing && (
        <div className="fixed inset-0 z-[100] bg-background  flex flex-col overflow-hidden">
          {/* FOCUS HEADER */}
          <div className="flex flex-wrap items-center justify-between gap-2 p-4 sm:px-6 border-b border-border bg-background  backdrop-blur-md z-10">
            <div className="flex min-w-0 items-center gap-2">
              <div className="p-2.5 bg-muted rounded-xl">
                <BookMarked className="h-5 w-5" />
              </div>
              <div>
                <h1 className="break-all text-lg font-semibold tracking-tight">{title}</h1>
                <p className="text-[10px] text-muted-foreground font-black uppercase tracking-widest">Focus view</p>
              </div>
            </div>

            <div className="flex items-center gap-3">
              <div className="flex items-center bg-muted p-1 rounded-full border border-border ">
                <Button
                  variant="ghost"
                  size="icon"
                  className="h-8 w-8 rounded-full cursor-pointer"
                  aria-label="Zoom out"
                  onClick={() => setZoomLevel(prev => Math.max(50, prev - 10))}
                >
                  <ZoomOut className="h-4 w-4" />
                </Button>
                <div className="px-3 min-w-[60px] text-center">
                  <span className="text-[11px] font-black font-mono">{zoomLevel}%</span>
                </div>
                <Button
                  variant="ghost"
                  size="icon"
                  className="h-8 w-8 rounded-full cursor-pointer"
                  aria-label="Zoom in"
                  onClick={() => setZoomLevel(prev => Math.min(200, prev + 10))}
                >
                  <ZoomIn className="h-4 w-4" />
                </Button>
                <div className="w-px h-4 bg-muted mx-1" />
                <Button
                  variant="ghost"
                  size="icon"
                  className="h-8 w-8 rounded-full cursor-pointer"
                  aria-label="Reset zoom"
                  onClick={() => setZoomLevel(100)}
                >
                  <RotateCcw className="h-3.5 w-3.5" />
                </Button>
              </div>

              <Button
                variant="outline"
                className="rounded-xl h-10 px-4 font-bold flex items-center gap-2 border-border hover:bg-accent  transition-all cursor-pointer"
                onClick={() => {
                  setIsFullScreen(false);
                  setZoomLevel(100);
                }}
              >
                <Minimize2 className="h-4 w-4" /> Exit focus
              </Button>
            </div>
          </div>

          {/* SCROLLABLE CONTENT */}
          <div className="flex-1 overflow-y-auto w-full custom-scrollbar scroll-smooth">
            <div className="min-h-full p-8 md:p-12 lg:p-20 flex justify-center">
              <div
                className="w-full max-w-4xl transition-all duration-200 origin-top"
                style={{ transform: `scale(${zoomLevel / 100})`, width: `${100 * (100 / zoomLevel)}%` }}
              >
                <div className="prose prose-lg dark:prose-invert max-w-none prose-headings:font-black prose-headings:tracking-tight prose-p:text-muted-foreground  prose-p:leading-relaxed prose-pre:bg-muted prose-pre:rounded-2xl pb-60">
                  <MarkdownRenderer noProse>{content}</MarkdownRenderer>
                </div>
              </div>
            </div>
          </div>
        </div>
      )}

      <WorkspaceHeader title="Notebook" description="Keep class notes and review them in one place." />

      <div className="flex flex-wrap items-center justify-between gap-2">
        <div className="flex flex-wrap items-center gap-2">
          <Button variant="outline" size="sm" aria-pressed={!isEditing} onClick={() => setIsEditing(!isEditing)}>
            {isEditing ? <><Eye /> Preview</> : <><PenLine /> Edit notes</>}
          </Button>
          {isEditing ? (
            <Select value={editorMode} onValueChange={(value: "rich-text" | "markdown") => setEditorMode(value)}>
              <SelectTrigger size="sm" aria-label="Editor format"><SelectValue /></SelectTrigger>
              <SelectContent>
                <SelectItem value="rich-text">Rich text</SelectItem>
                <SelectItem value="markdown">Markdown</SelectItem>
              </SelectContent>
            </Select>
          ) : (
            <Button variant="ghost" size="sm" onClick={() => setIsFullScreen(true)}>
              <Maximize2 /> Focus view
            </Button>
          )}
        </div>
        <div className="flex flex-wrap items-center gap-2">
          <Button variant={showCopilot ? "secondary" : "outline"} size="sm" aria-pressed={showCopilot} onClick={() => setShowCopilot(!showCopilot)}>
            <RaiseLogo size={16} aria-hidden /> Raise help
          </Button>
          <Button size="sm" onClick={saveNotebook} disabled={!hasUnsavedChanges || isSaving}>
            <Save /> {isSaving ? "Saving…" : "Save"}
          </Button>
        </div>
      </div>

      <div className={cn("grid overflow-hidden rounded-xl border border-border bg-card lg:grid-cols-[12rem_minmax(0,1fr)]", showCopilot && "xl:grid-cols-[12rem_minmax(0,1fr)_18rem]")}>
        {/* NOTEBOOKS LIST PANEL */}
        <section aria-labelledby="notebook-library" className="flex min-w-0 flex-col border-b border-border lg:border-b-0 lg:border-r">
            <div className="p-4 border-b border-border flex items-center justify-between">
              <h2 id="notebook-library" className="text-sm font-medium">My notebooks</h2>
              <Button
                variant="ghost"
                size="icon"
                className="h-6 w-6 rounded-full hover:bg-accent  cursor-pointer"
                aria-label="New notebook"
                onClick={createNewNotebook}
              >
                <Plus className="h-3.5 w-3.5" />
              </Button>
            </div>
            <div className="max-h-36 overflow-y-auto lg:max-h-[54dvh]">
              <div className="p-2 space-y-1">
                {notebooks.map((nb) => (
                  <div
                    key={nb.id}
                    className={cn(
                      "group flex items-center justify-between rounded-lg border",
                      activeNotebookId === nb.id
                        ? "bg-background  border-border shadow-sm"
                        : "border-transparent hover:bg-accent text-muted-foreground"
                    )}
                  >
                    <div className="flex min-w-0 flex-1 items-center px-2">
                      {editingTitleId === nb.id ? (
                        <input
                          autoFocus
                          aria-label="Rename notebook"
                          className="text-[11px] font-bold bg-transparent outline-none border-b border-border w-full"
                          defaultValue={nb.title}
                          onBlur={async (e) => {
                            const newTitle = e.target.value.trim() || "Untitled";
                            setEditingTitleId(null);
                            if (newTitle !== nb.title) {
                              await updateDoc(doc(db, "notebooks", nb.id), { title: newTitle });
                              if (activeNotebookId === nb.id) setTitle(newTitle);
                            }
                          }}
                          onKeyDown={async (e) => {
                            if (e.key === "Enter") {
                              const target = e.target as HTMLInputElement;
                              const newTitle = target.value.trim() || "Untitled";
                              setEditingTitleId(null);
                              if (newTitle !== nb.title) {
                                await updateDoc(doc(db, "notebooks", nb.id), { title: newTitle });
                                if (activeNotebookId === nb.id) setTitle(newTitle);
                              }
                            }
                          }}
                          onClick={(e) => e.stopPropagation()}
                        />
                      ) : (
                        <button
                          type="button"
                          className="min-w-0 flex-1 truncate rounded-sm py-2 text-left text-sm focus-visible:outline-2 focus-visible:outline-ring"
                          aria-current={activeNotebookId === nb.id ? "true" : undefined}
                          onClick={() => {
                            if (activeNotebookId === nb.id) return;
                            if (hasUnsavedChanges) saveNotebook();
                            setActiveNotebookId(nb.id);
                          }}
                        >
                          {nb.title || "Untitled"}
                        </button>
                      )}
                    </div>
                    <DropdownMenu>
                      <DropdownMenuTrigger asChild>
                        <Button
                          variant="ghost"
                          size="icon"
                          className="mr-1 size-7 shrink-0"
                          aria-label={`Options for ${nb.title || "Untitled"}`}
                          onClick={(e) => e.stopPropagation()}
                        >
                          <MoreVertical className="h-3 w-3" />
                        </Button>
                      </DropdownMenuTrigger>
                      <DropdownMenuContent align="end" className="w-32">
                        <DropdownMenuItem
                          className="text-[11px] font-bold py-2 cursor-pointer"
                          onClick={(e) => {
                            e.stopPropagation();
                            setEditingTitleId(nb.id);
                          }}
                        >
                          <PenLine className="h-3.5 w-3.5 mr-2" />
                          Rename
                        </DropdownMenuItem>
                        {notebooks.length > 1 && (
                          <DropdownMenuItem
                            className="text-red-500 dark:text-red-400 focus:text-red-500 text-[11px] font-bold py-2 cursor-pointer"
                            onClick={(e) => {
                              e.stopPropagation();
                              deleteNotebook(nb.id);
                            }}
                          >
                            <Trash2 className="h-3.5 w-3.5 mr-2" />
                            Delete
                          </DropdownMenuItem>
                        )}
                      </DropdownMenuContent>
                    </DropdownMenu>
                  </div>
                ))}
              </div>
            </div>
            <div className="p-3 border-t border-border bg-muted">
              <div className="flex items-center justify-between px-1">
                <span className="text-[9px] font-bold text-muted-foreground uppercase tracking-widest">
                  {notebooks.length} / {orgData?.notebookLimitPerStudent || 1} Used
                </span>
                {orgData?.subscriptionStatus === "none" && (
                  <Badge variant="outline" className="text-[8px] bg-muted border-border text-muted-foreground font-black px-1.5 py-0">FREE</Badge>
                )}
              </div>
            </div>
        </section>

        <section aria-label="Notes editor" className="flex h-[60dvh] min-h-96 min-w-0 flex-col">
          <div className="flex flex-wrap items-center justify-between gap-2 border-b border-border px-4 py-3">
            <input
              aria-label="Notebook title"
              value={title}
              onChange={(event) => {
                setTitle(event.target.value);
                setHasUnsavedChanges(true);
              }}
              className="min-w-0 flex-1 rounded-sm bg-transparent font-medium outline-none focus-visible:ring-2 focus-visible:ring-ring"
            />
            {lastSavedAt && <span className="text-xs text-muted-foreground" role="status">{hasUnsavedChanges ? "Unsaved changes" : "Saved"}</span>}
          </div>
            <div className="flex-1 overflow-hidden relative">
              {loading ? (
                <div className="h-full w-full flex items-center justify-center bg-muted backdrop-blur-sm">
                  <div className="text-center space-y-4">
                    <Loader2 className="h-8 w-8 animate-spin text-muted-foreground mx-auto" />
                    <p className="text-[10px] font-black uppercase text-muted-foreground tracking-[0.3em]">Loading notebooks…</p>
                  </div>
                </div>
              ) : isEditing ? (
                editorMode === "rich-text" ? (
                  <RichTextEditor
                    content={getHtml(content)}
                    onChange={handleRichTextChange}
                  />
                ) : (
                  <Textarea
                    value={content}
                    onChange={handleMarkdownChange}
                    placeholder="# Start your research summary here... \n\nUse Markdown for formatting, and ask the Copilot for help with synthesis!"
                    className="w-full h-full p-8 resize-none border-none focus-visible:ring-0 rounded-none font-mono text-sm leading-relaxed bg-transparent "
                  />
                )
              ) : (
                <ScrollArea className="h-full bg-background ">
                  <div className="p-8 pb-20">
                    <MarkdownRenderer className="min-h-full">
                      {content || "*Start typing to capture your research findings.*"}
                    </MarkdownRenderer>
                  </div>
                </ScrollArea>
              )}
            </div>
        </section>

        {showCopilot && (
          <section ref={helpPanelRef} aria-label="Raise help" className="flex h-[60dvh] min-h-96 min-w-0 flex-col border-t border-border lg:col-span-2 xl:col-span-1 xl:border-l xl:border-t-0">
              <div className="p-4 border-b border-border flex items-center justify-between bg-muted ">
                <Label className="text-[10px] font-black uppercase text-muted-foreground tracking-[0.2em] flex items-center gap-2">
                  <RaiseLogo className="h-3 w-3" /> Raise Help
                </Label>
                <div className="flex items-center gap-1">
                  {orgData?.aiNotebookLimitPerStudent > 0 && (
                    <div className="flex flex-col items-end mr-2">
                      <div className="flex items-center gap-1.5 mb-1">
                        <span className="text-[9px] font-bold text-muted-foreground uppercase tracking-tighter">Usage</span>
                        <span className="text-[10px] font-black tabular-nums">{studentUsage} / {orgData.aiNotebookLimitPerStudent}</span>
                      </div>
                      <div className="w-20 h-1 bg-muted rounded-full overflow-hidden">
                        <div
                          className={cn(
                            "h-full transition-all duration-500",
                            (studentUsage / orgData.aiNotebookLimitPerStudent) > 0.9 ? "bg-red-500" :
                              (studentUsage / orgData.aiNotebookLimitPerStudent) > 0.7 ? "bg-amber-500" : "bg-emerald-500"
                          )}
                          style={{ width: `${Math.min(100, (studentUsage / orgData.aiNotebookLimitPerStudent) * 100)}%` }}
                        />
                      </div>
                    </div>
                  )}
                  <Cpu className="h-3.5 w-3.5 text-muted-foreground " />
                  <Button
                    variant="ghost"
                    size="icon"
                    className="h-6 w-6 rounded-full hover:bg-accent  cursor-pointer"
                    aria-label="Close Raise help"
                    onClick={() => setShowCopilot(false)}
                  >
                    <X className="h-3 w-3" />
                  </Button>
                </div>
              </div>

              {/* CHAT AREA */}
              <ScrollArea className="flex-1 overflow-y-auto">
                <div className="p-4 space-y-4 pb-20">
                  {isAiDisabled && (
                    <div className="p-4 rounded-2xl border border-amber-200 bg-amber-50/50 dark:border-amber-900/40 dark:bg-amber-950/20 text-center space-y-2 mb-4">
                      <Crown className="h-5 w-5 text-amber-500 mx-auto" />
                      <h4 className="text-[11px] font-black uppercase text-amber-900 dark:text-amber-500 tracking-wider">Raise is unavailable</h4>
                      <p className="text-[10px] text-amber-800/70 dark:text-amber-500/60 font-medium leading-relaxed">
                        {studentUsage >= (orgData?.aiNotebookLimitPerStudent || 0) && (orgData?.aiNotebookLimitPerStudent || 0) > 0
                          ? "You have reached your personal monthly AI interaction limit."
                          : "Your network's monthly AI research budget has been reached."}
                        <br />Contact your instructor to unlock synthesis tools.
                      </p>
                    </div>
                  )}
                  {messages.length === 0 && (
                    <div className="text-center py-12 px-4 space-y-4">
                      <div className="inline-flex p-3 bg-muted rounded-2xl">
                        <RaiseLogo className="h-6 w-6 text-muted-foreground" />
                      </div>
                      <div>
                        <h3 className="text-xs font-bold text-foreground uppercase tracking-widest mb-1">Ask about your notes</h3>
                        <p className="text-[11px] text-muted-foreground leading-relaxed">
                          I can help you summarize your notes, suggest research topics,
                          or explain concepts you've written about.
                        </p>
                      </div>
                      <div className="grid grid-cols-1 gap-2 pt-2">
                        <Button variant="outline" size="sm" className="h-8 text-[10px] rounded-xl border-border text-muted-foreground hover:text-foreground transition-all  cursor-pointer" onClick={() => setInputValue("Can you summarize my current notes?")}>
                          Summarize my notes
                        </Button>
                        <Button variant="outline" size="sm" className="h-8 text-[10px] rounded-xl border-border text-muted-foreground hover:text-foreground transition-all  cursor-pointer" onClick={() => setInputValue("Give me 3 follow-up questions for research.")}>
                          Suggest research paths
                        </Button>
                      </div>
                    </div>
                  )}

                  {messages.map((m, idx) => (
                    <div key={idx} className={cn(
                      "flex flex-col gap-2 w-full",
                      m.role === 'user' ? "items-end" : "items-start"
                    )}>
                      <div className={cn(
                        "p-4 rounded-2xl text-[14px] leading-relaxed shadow-sm border max-w-[92%]",
                        m.role === 'user'
                          ? "bg-muted text-white border-border  font-medium"
                          : "bg-background text-foreground border-border  "
                      )}>
                        {m.role === 'assistant' ? (
                          <div className="prose prose-sm dark:prose-invert prose-p:leading-relaxed prose-pre:bg-muted prose-pre:p-2 prose-pre:rounded-lg">
                            <MarkdownRenderer noProse>{m.content}</MarkdownRenderer>
                          </div>
                        ) : m.content}
                      </div>
                    </div>
                  ))}

                  {isLoading && (
                    <div className="flex flex-col gap-2 max-w-[85%] items-start">
                      <div className="p-3 rounded-2xl border border-dashed border-border bg-muted flex items-center gap-2">
                        <div className="flex gap-1">
                          <span className="w-1.5 h-1.5 bg-muted rounded-full animate-bounce [animation-delay:-0.3s]"></span>
                          <span className="w-1.5 h-1.5 bg-muted rounded-full animate-bounce [animation-delay:-0.15s]"></span>
                          <span className="w-1.5 h-1.5 bg-muted rounded-full animate-bounce"></span>
                        </div>
                        <span className="text-[10px] text-muted-foreground font-bold uppercase tracking-widest">Processing</span>
                      </div>
                    </div>
                  )}
                  {/* Scroll Anchor */}
                  <div ref={scrollRef} className="h-1" />
                </div>
              </ScrollArea>

              {/* INPUT AREA */}
              <div className="p-4 border-t border-border bg-muted ">
                <div className="relative group">
                  <Textarea
                    aria-label="Message Raise"
                    value={inputValue}
                    onChange={(e) => setInputValue(e.target.value)}
                    onKeyDown={(e) => {
                      if (e.key === 'Enter' && !e.shiftKey) {
                        e.preventDefault();
                        handleSendMessage();
                      }
                    }}
                    disabled={isAiDisabled}
                    placeholder={isAiDisabled ? "AI Assistant Disabled" : "Ask Copilot..."}
                    className="min-h-[60px] max-h-[120px] pr-12 text-[12px] rounded-2xl border-border bg-background  shadow-sm transition-all focus-visible:ring-ring  disabled:opacity-50"
                  />
                  <Button
                    size="icon"
                    className="absolute bottom-2 right-2 size-8"
                    aria-label="Send message to Raise"
                    onClick={handleSendMessage}
                    disabled={!inputValue.trim() || isLoading || isAiDisabled}
                  >
                    <Send className="h-3.5 w-3.5" />
                  </Button>
                </div>
                <p className="mt-2 text-[9px] text-center text-muted-foreground uppercase tracking-widest font-bold">
                  AI uses network budget. Use wisely.
                </p>
              </div>
          </section>
        )}
      </div>

      <ConfirmDialog
        open={!!notebookToDelete}
        onOpenChange={(open) => !open && setNotebookToDelete(null)}
        title="Delete Notebook"
        description="Are you sure you want to delete this notebook? This cannot be undone."
        onConfirm={handleConfirmDelete}
        confirmText="Delete"
        cancelText="Cancel"
      />
    </div>
  );
}

"use client";
import { authenticatedFetch } from "@/lib/authenticated-fetch";

import { useRouter } from "next/navigation";
import { useEffect, useState } from "react";
import { collection, getDocs, query, where, doc, getDoc } from "firebase/firestore";
import { db } from "@/lib/firebase";
import { useAuth } from "@/contexts/auth-context";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { WorkspaceHeader, WorkspaceSummary } from "@/components/ui/workspace";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { ConfirmDialog } from "@/components/ui/confirm-dialog";
import { toast } from "sonner";
import { FileText, FileCheck, ArrowRight, PackageOpen, LayoutDashboard, GraduationCap, NotebookPen, ShieldCheck } from "lucide-react";
import { RaiseLogo } from "@/components/ui/raise-logo";
import Link from "next/link";
import { RundownDialog } from "@/components/ui/rundown-dialog";
import { StudentProgressChart } from "@/components/dashboard/student-progress-chart";

interface Stats {
  totalAssignments: number;
  completedAssignments: number;
  pendingAssignments: number;
}

interface RecentAssignment {
  id: string;
  title: string;
  dueDate: any;
  isSubmitted: boolean;
}

interface ScorePoint {
  title: string;
  score: number;
  date: string;
}

export default function StudentDashboard({ onLoaded }: { onLoaded?: () => void }) {
  const router = useRouter();
  const { user, profile } = useAuth();
  const [stats, setStats] = useState<Stats>({
    totalAssignments: 0,
    completedAssignments: 0,
    pendingAssignments: 0,
  });
  const [recentAssignments, setRecentAssignments] = useState<RecentAssignment[]>([]);
  const [recentScores, setRecentScores] = useState<ScorePoint[]>([]);
  const [teacherId, setTeacherId] = useState<string | null>(null);
  const [courseId, setCourseId] = useState<string | null>(null);
  const [teacherName, setTeacherName] = useState<string | null>(null);
  const [courseName, setCourseName] = useState<string | null>(null);
  const [courseCode, setCourseCode] = useState<string | null>(null);
  const [classCode, setClassCode] = useState("");
  const [joining, setJoining] = useState(false);
  const [leaving, setLeaving] = useState(false);
  const [showLeaveConfirm, setShowLeaveConfirm] = useState(false);
  const [dataReady, setDataReady] = useState(false);
  const [enrollmentReady, setEnrollmentReady] = useState(false);
  const [dashboardError, setDashboardError] = useState(false);
  const [enrollmentError, setEnrollmentError] = useState(false);
  const [firstSubmissionDone, setFirstSubmissionDone] = useState(false);
  const [retry, setRetry] = useState(0);

  useEffect(() => {
    if (dataReady && onLoaded) {
      onLoaded();
    }
  }, [dataReady, onLoaded]);

  const profileCourseId = profile?.courseId;
  const profileTeacherId = profile?.teacherId;
  const hasProfile = !!profile;
  useEffect(() => {
    if (!user || !hasProfile) return;
    let active = true;

    async function loadEnrollment() {
      try {
        const legacy = !profileCourseId && user ? (await getDoc(doc(db, "students", user.uid))).data() : null;
        const nextCourseId = profileCourseId || legacy?.courseId || null;
        const nextTeacherId = profileTeacherId || legacy?.teacherId || null;
        const course = nextCourseId ? (await getDoc(doc(db, "courses", nextCourseId))).data() : null;
        if (!active) return;
        setCourseId(nextCourseId);
        setTeacherId(nextTeacherId);
        setCourseName(course?.name || null);
        setCourseCode(course?.code || null);
        setEnrollmentReady(true);
      } catch (error) {
        console.error("Error syncing profile:", error);
        if (active) {
          setEnrollmentError(true);
          setDataReady(true);
        }
      }
    }

    loadEnrollment();
    return () => { active = false; };
  }, [user, hasProfile, profileCourseId, profileTeacherId, retry]);

  useEffect(() => {
    if (!user || !enrollmentReady) return;
    let active = true;

    async function fetchDashboardData() {
      if (!user) return;
      setDataReady(false);
      setDashboardError(false);
      try {
        if (teacherId) {
          const teacherDoc = await getDoc(doc(db, "teachers", teacherId)).catch(() => null);
          if (active) setTeacherName(teacherDoc?.data()?.name || null);
        } else {
          setTeacherName(null);
        }

        let totalAssignments = 0;
        let currentAssignmentIds = new Set<string>();
        let assignmentsList: any[] = [];

        // FETCHING LOGIC: Priority to courseId, fallback to teacherId (legacy)
        if (courseId) {
          const assignmentsSnap = await getDocs(
            query(collection(db, "assignments"), where("answerKeySeparated", "==", true), where("courseId", "==", courseId))
          );
          totalAssignments = assignmentsSnap.size;
          assignmentsSnap.docs.forEach(doc => {
            currentAssignmentIds.add(doc.id);
            assignmentsList.push({ id: doc.id, ...doc.data() });
          });
        } else if (teacherId) {
          // Fallback for legacy mode: fetch ALL assignments for this teacher
          // Note: If teacherId is a code, we'll try to resolve it first in syncTeacherId
          const assignmentsSnap = await getDocs(
            query(collection(db, "assignments"), where("answerKeySeparated", "==", true), where("teacherId", "==", teacherId), where("courseId", "==", null))
          );
          totalAssignments = assignmentsSnap.size;
          assignmentsSnap.docs.forEach(doc => {
            currentAssignmentIds.add(doc.id);
            assignmentsList.push({ id: doc.id, ...doc.data() });
          });
        }

        const submissionsSnap = await getDocs(
          query(collection(db, "submissions"), where("studentId", "==", user.uid))
        );

        const submissions = submissionsSnap.docs.map(d => ({ id: d.id, ...d.data() } as any));
        const submittedAssignmentIds = new Set(
          submissions.filter(data => data.status !== 'draft').map(data => data.assignmentId)
        );
        const completedAssignments = submissions.filter(data =>
          data.status !== 'draft' && currentAssignmentIds.has(data.assignmentId)
        ).length;

        // Map assignment title lookup
        const titleMap = new Map<string, string>();
        assignmentsList.forEach(a => titleMap.set(a.id, a.title || "Assignment"));

        // Extract score points sorted chronologically
        const gradedSubmissions = submissions
          .filter(s => s.graded && typeof s.score === 'number' && s.status !== 'draft' && currentAssignmentIds.has(s.assignmentId))
          .sort((a, b) => {
            const timeA = a.submittedAt?.seconds ? a.submittedAt.seconds * 1000 : (a.submittedAt ? new Date(a.submittedAt).getTime() : 0);
            const timeB = b.submittedAt?.seconds ? b.submittedAt.seconds * 1000 : (b.submittedAt ? new Date(b.submittedAt).getTime() : 0);
            return timeA - timeB;
          });

        const scorePoints: ScorePoint[] = gradedSubmissions.map(s => {
          const rawDate = s.submittedAt?.seconds ? new Date(s.submittedAt.seconds * 1000) : (s.submittedAt ? new Date(s.submittedAt) : null);
          return {
            title: titleMap.get(s.assignmentId) || "Assignment",
            score: s.score,
            date: rawDate ? rawDate.toLocaleDateString() : "",
          };
        });

        // Determine top upcoming assignments: unsubmitted first, sorted by due date ascending
        const upcoming: RecentAssignment[] = assignmentsList
          .map(a => ({
            id: a.id,
            title: a.title || "Untitled",
            dueDate: a.dueDate,
            isSubmitted: submittedAssignmentIds.has(a.id),
          }))
          .sort((a, b) => {
            if (a.isSubmitted !== b.isSubmitted) {
              return a.isSubmitted ? 1 : -1;
            }
            const timeA = a.dueDate?.seconds ? a.dueDate.seconds * 1000 : (a.dueDate ? new Date(a.dueDate).getTime() : Infinity);
            const timeB = b.dueDate?.seconds ? b.dueDate.seconds * 1000 : (b.dueDate ? new Date(b.dueDate).getTime() : Infinity);
            return timeA - timeB;
          })
          .slice(0, 3);

        if (!active) return;
        setFirstSubmissionDone(submittedAssignmentIds.size > 0);
        setStats({
          totalAssignments,
          completedAssignments,
          pendingAssignments: Math.max(0, totalAssignments - completedAssignments),
        });
        setRecentScores(scorePoints);
        setRecentAssignments(upcoming);
        setDataReady(true);
      } catch (error) {
        console.error("Error fetching data:", error);
        if (active) {
          setDashboardError(true);
          setDataReady(true);
        }
      }
    }

    fetchDashboardData();
    return () => { active = false; };
  }, [user, enrollmentReady, teacherId, courseId, retry]);

  function retryDashboard() {
    setEnrollmentError(false);
    setDashboardError(false);
    setEnrollmentReady(false);
    setDataReady(false);
    setRetry(value => value + 1);
  }

  const handleJoinClass = async () => {
    if (!user || !classCode) return;
    setJoining(true);
    try {
      const response = await authenticatedFetch('/api/student/enrollment', {
        method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ code: classCode.trim() }),
      });
      if (!response.ok) throw new Error((await response.json()).error);
      setClassCode("");
      toast.success('Joined class successfully');
      router.refresh(); // Refresh to pick up new claims without full reload
    } catch (error: any) {
      console.error("Error joining class:", error);
      toast.error(`Failed to join class: ${error.message}`);
    }
    finally {
      setJoining(false);
    }
  };

  const handleLeaveClass = async () => {
    if (!user) return;
    setLeaving(true);
    try {
      const response = await authenticatedFetch('/api/student/enrollment', {
        method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ action: 'leave' }),
      });
      if (!response.ok) throw new Error((await response.json()).error);
      setClassCode("");
      toast.success("Successfully left class.");
      router.refresh(); // Refresh to clear context without full reload
    } catch (error: any) {
      console.error("Error leaving class:", error);
      toast.error(`Failed to leave class: ${error.message}`);
    } finally {
      setLeaving(false);
    }
  };

  const firstAssignment = recentAssignments.find(assignment => !assignment.isSubmitted);

  const getGreeting = () => {
    const hour = new Date().getHours();
    if (hour < 12) return "Good morning";
    if (hour < 17) return "Good afternoon";
    return "Good evening";
  };

  return (
    <div className="space-y-6">
      <WorkspaceHeader
        title="Dashboard"
        description={`${getGreeting()}, ${profile?.displayName?.split(" ")[0] || "Student"}.`}
      >
        <RundownDialog
          userRole="student"
          triggerLabel="Student Tutorial"
          title="System Navigation Guide"
          steps={[
            {
              title: "1. The Student Dashboard",
              description: "Your primary overview page. See your class, coursework progress, and study tools.",
              icon: LayoutDashboard
            },
            {
              title: "2. Working on Assignments",
              description: "The core of the system. Select an assignment to begin solving problems. Use the Socratic AI chat to get help—but remember, the system is designed to guide you through steps, not give away answers.",
              icon: FileText
            },
            {
              title: "3. Reviewing Submissions",
              description: "Access your completed work. Review your answers and any feedback your instructor has shared.",
              icon: FileCheck
            },
            {
              title: "4. Grade Tracking",
              description: "View your current academic standing. See your scores and open feedback for each assignment.",
              icon: GraduationCap
            },
            {
              title: "5. Digital Notebook",
              description: "A persistent, Markdown-supported space for your notes. Use it to document derivations, save conceptual explanations, and prep for exams without switching platforms.",
              icon: NotebookPen
            },
            {
              title: "6. The Equation Vault",
              description: "Your searchable database for physics formulas and constants. You can quickly search for specific equations and reference them while working on problems.",
              icon: PackageOpen
            },
            {
              title: "7. Raise & Learning Library",
              description: "Access general conceptual help outside of specific assignments. If you're confused about a fundamental law of physics, use Raise for a deep-dive explanation or browse curated resources.",
              icon: RaiseLogo
            },
            {
              title: "8. Working with the Socratic AI",
              description: "To succeed, share your logic with the AI. If you're stuck, describe what you've tried or provide a partial derivation. The AI will analyze your work and provide a targeted hint to help you reach the next step.",
              icon: ShieldCheck,
              isSpecial: true
            }
