"use client";

import { useState, useEffect } from "react";
import { collection, getDocs, query, orderBy, where, doc, getDoc } from "firebase/firestore";
import { db } from "@/lib/firebase";
import { useAuth } from "@/contexts/auth-context";
import { WorkspaceHeader } from "@/components/ui/workspace";
import { Input } from "@/components/ui/input";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { ExternalLink, FileText, Search, Video, Globe } from "lucide-react";
import Link from "next/link";

interface Resource {
  id: string;
  title: string;
  url: string;
  createdAt: any;
  type?: "video" | "document" | "link";
  courseId?: string;
}

export default function StudentResourcesPage() {
  const { user, profile } = useAuth();
  const [resources, setResources] = useState<Resource[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState("");
  const [activeTab, setActiveTab] = useState("all");

  useEffect(() => {
    async function fetchResources() {
      if (!user) return;
      try {
        // Fetch student profile to get teacherId and courseId (Unified first)
        let teacherId = profile?.teacherId;
        let studentCourseId = profile?.courseId;

        if (!teacherId || !studentCourseId) {
          try {
            const studentDoc = await getDoc(doc(db, "students", user.uid));
            if (studentDoc.exists()) {
              const studentData = studentDoc.data();
              teacherId = teacherId || studentData.teacherId;
              studentCourseId = studentCourseId || studentData.courseId;
            }
          } catch (e) { console.error("Could not fetch legacy student profile", e); }
        }

        // --- LEGACY RESOLUTION START ---
        if (teacherId && !studentCourseId) {
           const codeMatch = await getDocs(query(collection(db, "courses"), where("code", "==", teacherId.trim())));
           if (!codeMatch.empty) {
              const courseDoc = codeMatch.docs[0];
              const courseData = courseDoc.data();
              studentCourseId = courseDoc.id;
              teacherId = courseData.teacherId;
           }
        }
        // --- LEGACY RESOLUTION END ---

        if (!teacherId) {
             setResources([]);
             setLoading(false);
             return;
        }

        // Fetch all resources for this teacher
        // Note: Filtering by course is done client-side so "All Classes" (null) resources are visible
        const q = query(
          collection(db, "resources"), 
          where("teacherId", "==", teacherId), 
          orderBy("createdAt", "desc")
        );

        const querySnapshot = await getDocs(q);
        const resourceList = querySnapshot.docs.map((doc) => ({
          id: doc.id,
          ...doc.data(),
        })) as Resource[];

        // Filter: include resources for specific course OR for all classes (null)
        const finalResources = resourceList.filter(r => 
          !r.courseId || r.courseId === studentCourseId
        );

        setResources(finalResources);
      } catch (error) {
        console.error("Error fetching resources:", error);
      } finally {
        setLoading(false);
      }
    }
    fetchResources();
  }, [user, profile]);

  const filteredResources = resources.filter(resource => {
    const matchesSearch = resource.title.toLowerCase().includes(searchQuery.toLowerCase());
    const matchesTab = activeTab === "all" || 
      (resource.type === activeTab) || 
      (activeTab === "video" && (resource.url.includes("youtube") || resource.url.includes("vimeo"))) ||
      (activeTab === "document" && (resource.url.includes(".pdf") || resource.url.includes(".doc")));
    return matchesSearch && matchesTab;
  });

  return (
    <div className="space-y-6">
      <WorkspaceHeader title="Resources" description="Study materials shared by your teacher." />

      <div className="flex flex-wrap items-center gap-2">
        <div className="relative min-w-0 flex-1 basis-48 sm:max-w-sm">
          <Search className="absolute left-2.5 top-2.5 h-4 w-4 text-muted-foreground" />
          <Input
            placeholder="Search resources…"
            aria-label="Search resources"
            className="pl-8"
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
          />
        </div>
        <Select value={activeTab} onValueChange={setActiveTab}>
          <SelectTrigger aria-label="Resource type">
            <SelectValue placeholder="All Types" />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="all" className="cursor-pointer">All Types</SelectItem>
            <SelectItem value="video" className="cursor-pointer">Videos</SelectItem>
            <SelectItem value="document" className="cursor-pointer">Documents</SelectItem>
            <SelectItem value="link" className="cursor-pointer">Websites</SelectItem>
          </SelectContent>
        </Select>
      </div>

      <div className="overflow-hidden rounded-xl border border-border bg-card">
        {loading ? (
          <p role="status" className="p-6 text-sm text-muted-foreground">Loading resources…</p>
        ) : filteredResources.length === 0 ? (
          <p className="p-6 text-sm text-muted-foreground">
            {resources.length ? "No resources match your filters." : "Your teacher hasn’t shared any resources yet."}
          </p>
        ) : (
          <ul className="divide-y divide-border">
            {filteredResources.map((resource) => {
              const Icon = resource.type === "video" || /youtube|vimeo/.test(resource.url)
                ? Video
                : resource.type === "document" || /\.pdf|\.doc/.test(resource.url) ? FileText : Globe;
              return (
                <li key={resource.id}>
                  <Link href={resource.url} target="_blank" rel="noopener noreferrer" className="flex items-center gap-3 px-4 py-4 hover:bg-accent focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-ring sm:px-5">
                    <Icon className="size-4 shrink-0 text-muted-foreground" />
                    <div className="min-w-0 flex-1">
                      <h2 className="break-words text-sm font-medium">{resource.title}</h2>
                      <p className="text-xs capitalize text-muted-foreground">
                        {resource.type || "Link"}
                        {resource.createdAt?.toDate && ` · ${resource.createdAt.toDate().toLocaleDateString()}`}
                      </p>
                    </div>
                    <ExternalLink className="size-4 shrink-0 text-muted-foreground" />
                    <span className="sr-only">(opens in a new tab)</span>
                  </Link>
                </li>
              );
            })}
          </ul>
        )}
      </div>
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { collection, query, where, doc, getDoc, onSnapshot } from "firebase/firestore";
import { db } from "@/lib/firebase";
import { useAuth } from "@/contexts/auth-context";
import { Card, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { WorkspaceHeader } from "@/components/ui/workspace";
import Link from "next/link";
import { Button } from "@/components/ui/button";

interface Submission {
  id: string;
  assignmentId: string;
  assignmentTitle: string;
  answers: any[];
  submittedAt: Date | null;
  graded: boolean;
  score: number | null;
  feedback?: string;
  status?: string;
}

export default function SubmissionsPage() {
  const { user, profile } = useAuth();
  const [submissions, setSubmissions] = useState<Submission[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!user) return;

    // 1. Listen for new submissions in real-time
    const q = query(collection(db, "submissions"), where("studentId", "==", user.uid));
    const unsubscribe = onSnapshot(q, async (snapshot) => {
      const submissionsData: (Submission | null)[] = await Promise.all(
        snapshot.docs.map(async (submissionDoc) => {
          const data = submissionDoc.data();
          try {
            // Fetch Assignment Details (Cache these maybe? For now just fetch)
            const assignmentDoc = await getDoc(doc(db, "assignments", data.assignmentId));
            if (!assignmentDoc.exists()) return null;

            const assignData = assignmentDoc.data();

            // Filter logic
            if (profile?.courseId) {
                if (assignData.courseId !== profile.courseId) return null;
            } else if (profile?.teacherId && assignData.teacherId && profile.teacherId !== assignData.teacherId) {
                return null;
            }

            return {
              id: submissionDoc.id,
              assignmentId: data.assignmentId,
              assignmentTitle: assignData.title,
              answers: data.answers || [],
              submittedAt: data.submittedAt?.toDate?.() || (data.submittedAt ? new Date(data.submittedAt) : null),
              graded: data.graded || false,
              score: data.score ?? null,
              feedback: data.feedback ?? "",
              status: data.status || (data.graded ? 'graded' : 'submitted'),
            } satisfies Submission;
          } catch (e) {
            console.error("Error fetching assignment for submission:", e);
            return null;
          }
        })
      );

      const filteredSubmissions = submissionsData.filter((s): s is Submission => s !== null && s.status !== 'draft');
      // Sort by submittedAt descending
      filteredSubmissions.sort((a, b) => {
        const dateA = a.submittedAt ? new Date(a.submittedAt).getTime() : 0;
        const dateB = b.submittedAt ? new Date(b.submittedAt).getTime() : 0;
        return dateB - dateA;
      });
      setSubmissions(filteredSubmissions);
      setLoading(false);
    });

    return () => unsubscribe();
  }, [user]);

  return (
    <div className="space-y-6">
      <WorkspaceHeader title="My Submissions" description="Check which assignments you’ve turned in.">
        <Button asChild variant="outline"><Link href="/student/grades">View grades</Link></Button>
      </WorkspaceHeader>

      <Card className="overflow-hidden py-0 shadow-none">
        <CardContent className="p-0">
          {loading ? (
            <p role="status" className="p-6 text-sm text-muted-foreground">Loading submissions…</p>
          ) : submissions.length === 0 ? (
            <p className="p-6 text-sm text-muted-foreground">Your submitted assignments will appear here.</p>
          ) : (
            <Table aria-label="Submission history">
              <TableHeader className="bg-muted/40">
                <TableRow>
                  <TableHead className="px-4">Assignment</TableHead>
                  <TableHead>Status</TableHead>
                  <TableHead>Score</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {submissions.map((submission) => (
                  <TableRow key={submission.id}>
                    <TableCell className="min-w-32 whitespace-normal px-4 py-3 font-medium">
                      <span className="break-words">{submission.assignmentTitle}</span>
                      <p className="text-xs font-normal text-muted-foreground">{submission.submittedAt?.toLocaleDateString() ?? "—"}</p>
                    </TableCell>
                    <TableCell>
                      {submission.graded ? (
                        <Badge variant="secondary">
                          Graded
                        </Badge>
                      ) : (
                        <Badge variant="outline">
                          Awaiting grade
                        </Badge>
                      )}
                    </TableCell>
                    <TableCell>
                      {submission.graded && submission.score !== null
                        ? `${submission.score}%`
                        : "-"}
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

