export default function Vault() {
  const { profile } = useAuth();
  const [courseName, setCourseName] = useState<string | null>(null);
  const [restrictedIds, setRestrictedIds] = useState<string[]>([]);
  const [customFormulas, setCustomFormulas] = useState<Formula[]>([]);
  const [search, setSearch] = useState("");
  const [activeCategory, setActiveCategory] = useState("all");
  const [viewMode, setViewMode] = useState<"grid" | "list">("grid");
  const [copiedId, setCopiedId] = useState<string | null>(null);

  useEffect(() => {
    async function fetchCourse() {
      if (profile?.courseId) {
        const courseDoc = await getDoc(doc(db, "courses", profile.courseId));
        if (courseDoc.exists()) {
          const data = courseDoc.data();
          setCourseName(data.name);
          setRestrictedIds(data.restrictedFormulaIds || []);
          setCustomFormulas(data.customFormulas || []);
        }
      }
    }
    fetchCourse();
  }, [profile?.courseId]);

  const handleCopy = (formula: Formula) => {
    navigator.clipboard.writeText(formula.formula || formula.latex);
    setCopiedId(formula.id);
    toast.success(`${formula.name} copied to clipboard!`);
    setTimeout(() => setCopiedId(null), 2000);
  };

  const allFormulas = [...FORMULAS, ...customFormulas];

  const filteredFormulas = allFormulas.filter(formula => {
    // Check if formula is restricted by teacher
    if (restrictedIds.includes(formula.id)) return false;

    const matchesSearch = formula.name.toLowerCase().includes(search.toLowerCase()) || 
                         formula.formula.toLowerCase().includes(search.toLowerCase()) ||
                         formula.description.toLowerCase().includes(search.toLowerCase());
    const matchesCategory = activeCategory === "all" || formula.category === activeCategory;
    return matchesSearch && matchesCategory;
  });

  return (
    <div className="space-y-6">

      <WorkspaceHeader title="Equation Vault" description={`Search formulas and constants for ${courseName || "physics"}.`} />
      <div className="flex flex-wrap items-center gap-2">
        <div className="relative min-w-0 flex-1 basis-48 sm:max-w-sm">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
          <Input
            placeholder="Search formulas…"
            aria-label="Search formulas"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="pl-9"
          />
        </div>
        <Select value={activeCategory} onValueChange={setActiveCategory}>
          <SelectTrigger aria-label="Formula category"><SelectValue /></SelectTrigger>
          <SelectContent>
            {CATEGORIES.map((category) => (
              <SelectItem key={category.id} value={category.id}>{category.name}</SelectItem>
            ))}
          </SelectContent>
        </Select>
        <div className="flex gap-1" role="group" aria-label="Formula layout">
          <Button variant={viewMode === "grid" ? "default" : "outline"} size="icon" onClick={() => setViewMode("grid")} aria-label="Grid view" aria-pressed={viewMode === "grid"}><LayoutGrid /></Button>
          <Button variant={viewMode === "list" ? "default" : "outline"} size="icon" onClick={() => setViewMode("list")} aria-label="List view" aria-pressed={viewMode === "list"}><List /></Button>
        </div>
      </div>

      {restrictedIds.length > 0 && <p className="text-sm text-muted-foreground">Your class can only see formulas approved by your teacher.</p>}

      {filteredFormulas.length === 0 ? (
        <div className="rounded-xl border border-border bg-card p-6 text-center">
          <PackageOpen className="mx-auto mb-2 size-5 text-muted-foreground" />
          <p className="font-medium">Nothing found in the vault.</p>
          <p className="text-sm text-muted-foreground">Try another search or category.</p>
        </div>
      ) : viewMode === "grid" ? (
        <div className="grid gap-3 lg:grid-cols-2 xl:grid-cols-3">
          {filteredFormulas.map(formula => (
            <Card 
              key={formula.id} 
              className="min-w-0 gap-3 py-4 shadow-none"
            >
              <CardHeader className="px-4">
                <div className="flex flex-wrap justify-between gap-2">
                   <CardTitle className="break-words text-base">{formula.name}</CardTitle>
                   <div className="flex items-center gap-2">
                     <Badge variant="secondary" className="capitalize">
                       {formula.category}
                     </Badge>
                   </div>
                </div>
                <CardDescription className="break-words text-sm">{formula.description}</CardDescription>
              </CardHeader>
              <CardContent className="space-y-3 px-4">
                <div className="flex items-center gap-2 rounded-lg bg-muted/50 px-3">
                  <div className="min-w-0 flex-1 overflow-x-auto py-3 text-center"><InlineMath math={formula.latex} /></div>
                  <Button variant="ghost" size="icon-sm" onClick={() => handleCopy(formula)} aria-label={copiedId === formula.id ? `Copied ${formula.name}` : `Copy ${formula.name}`}>
                    {copiedId === formula.id ? <Check /> : <Copy />}
                  </Button>
                </div>
                <div className="space-y-1">
                  {formula.variables && Object.entries(formula.variables).map(([symbol, name]) => (
                    <div key={symbol} className="flex items-start gap-2 text-xs text-muted-foreground">
                      <span className="shrink-0 font-mono text-foreground">{symbol}</span>
                      <span className="break-words">{name}</span>
                    </div>
                  ))}
                  {!formula.variables && (
                    <div className="flex items-start gap-2 text-xs text-muted-foreground italic">
                      No variable definitions provided.
                    </div>
                  )}
                </div>
              </CardContent>
            </Card>
          ))}
        </div>
      ) : (
        <ul className="divide-y divide-border rounded-xl border border-border bg-card">
          {filteredFormulas.map((formula) => (
            <li key={formula.id} className="flex flex-wrap items-center gap-3 px-4 py-3">
              <div className="min-w-0 flex-1 basis-48">
                <h2 className="break-words text-sm font-medium">{formula.name}</h2>
                <p className="break-words text-xs text-muted-foreground">{formula.description}</p>
              </div>
              <div className="min-w-0 max-w-full overflow-x-auto"><InlineMath math={formula.latex} /></div>
              <Badge variant="outline" className="capitalize">{formula.category}</Badge>
              <Button variant="ghost" size="icon-sm" onClick={() => handleCopy(formula)} aria-label={copiedId === formula.id ? `Copied ${formula.name}` : `Copy ${formula.name}`}>
                {copiedId === formula.id ? <Check /> : <Copy />}
              </Button>
            </li>
          ))}
        </ul>
      )}

      <details className="rounded-xl border border-border bg-card">
        <summary className="cursor-pointer px-4 py-3 text-sm font-medium">Universal constants</summary>
        <dl className="grid gap-3 border-t border-border p-4 sm:grid-cols-2">
          {[
            { s: "g", v: "9.81 m/s²", n: "Gravity" },
            { s: "G", v: "6.67 × 10⁻¹¹", n: "Gravitation" },
            { s: "c", v: "3.00 × 10⁸ m/s", n: "Light speed" },
            { s: "h", v: "6.63 × 10⁻³⁴ Js", n: "Planck’s constant" },
          ].map((item) => (
            <div key={item.s} className="text-sm">
              <dt className="text-muted-foreground">{item.n}</dt>
              <dd className="font-mono">{item.s} = {item.v}</dd>
            </div>
          ))}
        </dl>
      </details>
    </div>
  );
}

"use client";
import { getTeacherAssignment } from "@/lib/authenticated-fetch";

import { useEffect, useState, Suspense } from "react";
import { useSearchParams } from "next/navigation";
import { doc, getDoc, collection, query, where, getDocs } from "firebase/firestore";
import { db } from "@/lib/firebase";
import { useAuth } from "@/contexts/auth-context";
import { Card, CardContent, CardHeader } from "@/components/ui/card";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Button } from "@/components/ui/button";
import { ArrowLeft, Download, ChevronRight } from "lucide-react";
import Link from "next/link";
import { downloadCSV } from "@/lib/utils";
import { TeacherPageHeader, TeacherSummary } from "@/components/teacher/workspace";
import { LoadingSpinner } from "@/components/ui/loading-spinner";

interface Assignment {
  id: string;
  title: string;
  description: string;
  dueDate: any;
}

interface Submission {
  id: string;
  studentId: string;
  studentName?: string; // We might need to fetch this or store it in submission
  studentEmail?: string;
  submittedAt: any;
  answers: any;
  score?: number | null;
}

function AssignmentDetailsContent() {
  const { user } = useAuth();
  const searchParams = useSearchParams();
  const assignmentId = searchParams ? searchParams.get("id") ?? "" : "";

  const [assignment, setAssignment] = useState<Assignment | null>(null);
  const [submissions, setSubmissions] = useState<Submission[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    async function fetchData() {
      if (!assignmentId || !user) return;

      try {
        const assignmentDoc = await getTeacherAssignment(assignmentId);
        if (assignmentDoc.exists()) {
            const data = assignmentDoc.data();
            if (data.teacherId && data.teacherId !== user.uid) {
                setLoading(false);
                return;
            }
          setAssignment({ id: assignmentDoc.id, ...data } as Assignment);
        } else {
            setLoading(false);
            return;
        }

        const q = query(collection(db, "submissions"), where("assignmentId", "==", assignmentId));
        const snapshot = await getDocs(q);

        const submissionsData = await Promise.all(snapshot.docs.map(async (docSnapshot) => {
          const data = docSnapshot.data();

          // Filter out draft submissions
          if (data.status === 'draft') return null;

          // Use studentName and studentEmail from submission document
          let studentName = data.studentName || "Unknown Student";
          let studentEmail = data.studentEmail || "";

          // Fallback to users collection if name is missing
          if (studentName === "Unknown Student" && data.studentId) {
            try {
              const userDoc = await getDoc(doc(db, "users", data.studentId));
              if (userDoc.exists()) {
                const userData = userDoc.data();
                studentName = userData.displayName || userData.name || "Unknown Student";
                studentEmail = userData.email || studentEmail;
              }
            } catch (error) {
              console.error(`Error fetching user ${data.studentId}:`, error);
            }
          }

          return {
            id: docSnapshot.id,
            ...data,
            studentName,
            studentEmail,
            submittedAt: data.submittedAt?.toDate?.() || new Date(data.submittedAt),
          };
        }));

        // Filter out null entries (draft submissions)
        setSubmissions(submissionsData.filter(s => s !== null) as Submission[]);
      } catch (error) {
        console.error("Error fetching data:", error);
      } finally {
        setLoading(false);
      }
    }

    fetchData();
  }, [assignmentId, user]);

  if (loading) {
    return <LoadingSpinner fullPage />;
  }

  if (!assignment) {
    return (
      <div className="flex flex-col items-center justify-center py-20 text-center">
        <p className="text-xl font-bold">Assignment not found</p>
        <Button variant="outline" className="mt-4" asChild>
          <Link href="/teacher/assignments">Return to List</Link>
        </Button>
      </div>
    );
  }

  const scores = submissions.flatMap(({ score }) => typeof score === "number" ? [score] : []);
  const gradedCount = scores.length;
  const averageScore = gradedCount ? Math.round(scores.reduce((total, score) => total + score, 0) / gradedCount) : 0;

  const dueDate = new Date(assignment.dueDate?.toDate?.() || assignment.dueDate);

  return (
    <div className="space-y-6">
      <Link href="/teacher/assignments" className="inline-flex items-center gap-2 text-sm text-muted-foreground hover:text-foreground">
        <ArrowLeft className="size-4" /> Assignments
      </Link>

      <TeacherPageHeader title={assignment.title} description={assignment.description}>
        <Button
          variant="outline"
          disabled={submissions.length === 0}
          onClick={() => {
            const rows = submissions.map((submission) => ({
              submissionId: submission.id,
              studentId: submission.studentId,
              studentName: submission.studentName,
              studentEmail: submission.studentEmail,
              submittedAt: submission.submittedAt?.toString?.() || String(submission.submittedAt),
              score: submission.score ?? "",
              graded: typeof submission.score === "number" ? "true" : "false",
            }));
            downloadCSV(`${assignment.title || "assignment"}-grades.csv`, rows);
          }}
        >
          <Download /> Export CSV
        </Button>
      </TeacherPageHeader>

      <TeacherSummary
        label="Assignment overview"
        items={[
          { label: "Submissions", value: submissions.length },
          { label: "Graded", value: gradedCount },
          { label: "Average score", value: gradedCount ? `${averageScore}%` : "—" },
          { label: "Due date", value: Number.isNaN(dueDate.getTime()) ? "—" : dueDate.toLocaleDateString() },
        ]}
      />

      <Card className="min-w-0 gap-0 py-0">
        <CardHeader className="px-4 py-4 sm:px-5">
          <h2 className="text-base font-semibold">Submissions</h2>
        </CardHeader>
        <CardContent className="border-t p-0">
          {submissions.length === 0 ? (
            <p className="px-5 py-10 text-center text-sm text-muted-foreground">No submissions yet.</p>
          ) : (
            <Table aria-label="Assignment submissions">
              <TableHeader className="bg-muted/40">
                <TableRow>
                  <TableHead className="pl-4 sm:pl-5">Student</TableHead>
                  <TableHead>Submitted</TableHead>
                  <TableHead>Score</TableHead>
                  <TableHead className="text-right pr-4 sm:pr-5">Review</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {submissions.map((submission) => (
                  <TableRow key={submission.id}>
                    <TableCell className="max-w-64 whitespace-normal py-3 pl-4 sm:pl-5">
                      <p className="break-words font-medium">{submission.studentName}</p>
                      <p className="break-all text-xs text-muted-foreground">{submission.studentEmail}</p>
                    </TableCell>
                    <TableCell>
                      <p className="text-sm">{submission.submittedAt.toLocaleDateString()}</p>
                      <p className="text-xs text-muted-foreground">
                        {submission.submittedAt.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" })}
                      </p>
                    </TableCell>
                    <TableCell className="font-medium tabular-nums">
                      {typeof submission.score === "number" ? `${submission.score}%` : <span className="text-muted-foreground">Pending</span>}
                    </TableCell>
                    <TableCell className="text-right pr-4 sm:pr-5">
                      <Button asChild variant={typeof submission.score === "number" ? "ghost" : "outline"} size="sm">
                        <Link href={`/teacher/submission/grade?id=${submission.id}`}>
                          {typeof submission.score === "number" ? "Review" : "Grade"} <ChevronRight />
                        </Link>
                      </Button>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

export default function AssignmentDetailsPage() {
  return (
    <Suspense fallback={<LoadingSpinner fullPage />}>
      <AssignmentDetailsContent />
    </Suspense>
  );
}

"use client";

import { useEffect, useState } from "react";
import Link from "next/link";
