interface Assignment {
  id: string;
  title: string;
  description: string;
  dueDate: Date;
  questions?: { points?: number }[];
  createdAt: Date;
  courseId?: string;
  courseName?: string;
  visibility?: "private" | "network" | "global";
  organizationId?: string;
  lockdownMode?: boolean;
}

export default function AssignmentsPage() {
  const { user } = useAuth();
  const router = useRouter();
  const [assignments, setAssignments] = useState<Assignment[]>([]);
  const [loading, setLoading] = useState(true);
  const [courses, setCourses] = useState<{id: string, name: string}[]>([]);
  const [selectedCourseId, setSelectedCourseId] = useState<string>("all");
  const [filter, setFilter] = useState<string>("all");
  const [sort, setSort] = useState<string>("dueDateDesc");
  const [assignmentToDelete, setAssignmentToDelete] = useState<string | null>(null);

  useEffect(() => {
    async function fetchCourses() {
       if (!user) return;
       try {
         const snap = await getDocs(query(collection(db, "courses"), where("teacherId", "==", user.uid)));
         setCourses(snap.docs.map(d => ({ id: d.id, name: d.data().name })));
       } catch (e) { console.error(e); }
    }
    fetchCourses();
  }, [user]);

  useEffect(() => {
    if (user) {
      fetchAssignments();
    }
  }, [user]);

  async function fetchAssignments() {
    if (!user) return;
    try {
      // 1. Fetch courses to map names
      const coursesSnap = await getDocs(query(collection(db, "courses"), where("teacherId", "==", user.uid)));
      const courseMap: Record<string, string> = {};
      coursesSnap.docs.forEach(d => courseMap[d.id] = d.data().name);

      // 2. Fetch assignments
      const q = query(collection(db, "assignments"), where("teacherId", "==", user.uid));
      const snapshot = await getDocs(q);
      const data = snapshot.docs.map((doc) => {
        const d = doc.data();
        return {
          id: doc.id,
          ...d,
          dueDate: d.dueDate?.toDate?.() || new Date(d.dueDate),
          createdAt: d.createdAt?.toDate?.() || new Date(d.createdAt),
          courseName: d.courseId ? courseMap[d.courseId] : undefined
        };
      }) as Assignment[];
      setAssignments(data);
    } catch (error) {
      console.error("Error fetching assignments:", error);
    } finally {
      setLoading(false);
    }
  }

  async function handleDuplicate(assignment: Assignment) {
    if (!user) return;
    try {
      const full = await getTeacherAssignment(assignment.id);
      const fullData = full.data();
      const waypointData = {
        ...fullData,
        title: `${assignment.title} (Copy)`,
      };
      sessionStorage.setItem("forked_assignment", JSON.stringify(waypointData));
      router.push("/teacher/create?fork=true");
    } catch {
      const waypointData = {
        title: `${assignment.title} (Copy)`,
        description: assignment.description,
        dueDate: assignment.dueDate,
        questions: assignment.questions,
        visibility: assignment.visibility,
        lockdownMode: assignment.lockdownMode,
      };
      sessionStorage.setItem("forked_assignment", JSON.stringify(waypointData));
      router.push("/teacher/create?fork=true");
    }
  }

  async function handleDelete(id: string) {
    try {
      await deleteDoc(doc(db, "assignments", id));
      setAssignments(assignments.filter((a) => a.id !== id));
      toast.success("Assignment deleted.");
    } catch (error) {
      console.error("Error deleting assignment:", error);
      toast.error("Failed to delete assignment.");
    }
  }

  async function updateVisibility(id: string, visibility: "private" | "network" | "global") {
    try {
      await updateDoc(doc(db, "assignments", id), { visibility });
      setAssignments(assignments.map(a => a.id === id ? { ...a, visibility } : a));
    } catch (error) {
      console.error("Error updating visibility:", error);
    }
  }

  const isPastDue = (date: Date) => new Date(date) < new Date();

  // Filtering
  let filteredAssignments = assignments.filter((assignment) => {
    if (selectedCourseId !== "all" && assignment.courseId !== selectedCourseId) return false;

    const pastDue = isPastDue(assignment.dueDate);
    if (filter === "active") return !pastDue;
    if (filter === "pastDue") return pastDue;
    return true;
  });

  // Sorting
  filteredAssignments = filteredAssignments.sort((a, b) => {
    if (sort === "dueDateAsc") {
      return new Date(a.dueDate).getTime() - new Date(b.dueDate).getTime();
    } else if (sort === "dueDateDesc") {
      return new Date(b.dueDate).getTime() - new Date(a.dueDate).getTime();
    } else if (sort === "titleAsc") {
      return a.title.localeCompare(b.title);
    } else if (sort === "titleDesc") {
      return b.title.localeCompare(a.title);
    }
    return 0;
  });

  return (
    <div className="space-y-6">
      <TeacherPageHeader title="Assignments" description="Review deadlines, manage sharing, and open student submissions.">
        <Button asChild>
          <Link href="/teacher/create"><PlusCircle /> Create Assignment</Link>
        </Button>
      </TeacherPageHeader>

      <Card className="min-w-0 gap-0 py-0">
        <CardHeader className="flex flex-wrap items-end justify-between gap-3 px-4 py-4 sm:px-5">
          <div className="grid w-full max-w-xl gap-3 sm:grid-cols-3">
            <div className="min-w-0 space-y-1.5">
              <label htmlFor="assignment-class" className="block text-xs font-medium text-muted-foreground">Class</label>
              <Select value={selectedCourseId} onValueChange={setSelectedCourseId}>
                <SelectTrigger id="assignment-class" className="w-full cursor-pointer">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All Classes</SelectItem>
                  {courses.map((course) => <SelectItem key={course.id} value={course.id}>{course.name}</SelectItem>)}
                </SelectContent>
              </Select>
            </div>
            <div className="min-w-0 space-y-1.5">
              <label htmlFor="assignment-status" className="block text-xs font-medium text-muted-foreground">Status</label>
              <Select value={filter} onValueChange={setFilter}>
                <SelectTrigger id="assignment-status" className="w-full cursor-pointer">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All Statuses</SelectItem>
                  <SelectItem value="active">Active</SelectItem>
                  <SelectItem value="pastDue">Past Due</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div className="min-w-0 space-y-1.5">
              <label htmlFor="assignment-sort" className="block text-xs font-medium text-muted-foreground">Sort by</label>
              <Select value={sort} onValueChange={setSort}>
                <SelectTrigger id="assignment-sort" className="w-full cursor-pointer">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="dueDateDesc">Due Date (Latest)</SelectItem>
                  <SelectItem value="dueDateAsc">Due Date (Earliest)</SelectItem>
                  <SelectItem value="titleAsc">Title (A–Z)</SelectItem>
                  <SelectItem value="titleDesc">Title (Z–A)</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>
          {!loading && <p className="text-sm text-muted-foreground">{filteredAssignments.length} assignments</p>}
        </CardHeader>
        <CardContent className="border-t p-0">
          {loading || filteredAssignments.length === 0 ? (
            <p role="status" className="px-5 py-10 text-center text-sm text-muted-foreground">
              {loading ? "Loading assignments…" : "No assignments match these filters."}
            </p>
          ) : (
            <Table aria-label="Assignments">
              <TableHeader className="bg-muted/40">
                <TableRow>
                  <TableHead className="pl-4 sm:pl-5">Assignment</TableHead>
                  <TableHead>Deadline</TableHead>
                  <TableHead>Visibility</TableHead>
                  <TableHead className="w-12"><span className="sr-only">Actions</span></TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {filteredAssignments.map((assignment) => (
                  <TableRow key={assignment.id}>
                    <TableCell className="max-w-80 whitespace-normal py-3 pl-4 sm:pl-5">
                      <Link
                        href={`/teacher/assignment-view?id=${assignment.id}`}
                        className="inline-flex items-baseline gap-1.5 break-words font-medium hover:text-primary hover:underline"
                      >
                        {assignment.title}
                        <ArrowUpRight aria-hidden="true" className="size-3 shrink-0 text-muted-foreground" />
                      </Link>
                      <div className="mt-1 flex flex-wrap items-center gap-x-2 gap-y-1 text-xs text-muted-foreground">
                        <span>{assignment.courseName || (assignment.courseId ? "Unknown class" : "All classes")}</span>
                        <span>{assignment.questions?.length || 0} questions · {getAssignmentPoints(assignment.questions)} pts</span>
                        {assignment.lockdownMode && (
                          <span className="inline-flex items-center gap-1"><ShieldAlert aria-hidden="true" className="size-3" /> Lockdown</span>
                        )}
                      </div>
                    </TableCell>
                    <TableCell className="text-xs">
                      <p className="font-medium">{Number.isNaN(assignment.dueDate.getTime()) ? "No due date" : assignment.dueDate.toLocaleDateString()}</p>
                      <p className="text-muted-foreground">{isPastDue(assignment.dueDate) ? "Past due" : "Active"}</p>
                    </TableCell>
                    <TableCell>
                      <Select
                        value={assignment.visibility || "private"}
                        onValueChange={(value: "private" | "network" | "global") => updateVisibility(assignment.id, value)}
                      >
                        <SelectTrigger size="sm" aria-label={`Visibility for ${assignment.title}`} className="cursor-pointer text-xs">
                          <SelectValue />
                        </SelectTrigger>
                        <SelectContent>
                          <SelectItem value="private"><Lock /> Private</SelectItem>
                          <SelectItem value="network"><ShieldCheck /> Network</SelectItem>
                          <SelectItem value="global"><Globe /> Global</SelectItem>
                        </SelectContent>
                      </Select>
                    </TableCell>
                    <TableCell className="pr-3">
                      <DropdownMenu>
                        <DropdownMenuTrigger asChild>
                          <Button variant="ghost" size="icon-sm" aria-label={`Actions for ${assignment.title}`}>
                            <MoreHorizontal />
                          </Button>
                        </DropdownMenuTrigger>
                        <DropdownMenuContent align="end">
                          <DropdownMenuItem onSelect={() => handleDuplicate(assignment)}><Copy /> Duplicate</DropdownMenuItem>
                          <DropdownMenuItem variant="destructive" onSelect={() => setAssignmentToDelete(assignment.id)}>
                            <Trash2 /> Delete assignment
                          </DropdownMenuItem>
                        </DropdownMenuContent>
                      </DropdownMenu>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          )}
        </CardContent>
      </Card>

      <ConfirmDialog
        open={!!assignmentToDelete}
        onOpenChange={(open) => !open && setAssignmentToDelete(null)}
        title="Delete Assignment"
        description="Are you sure you want to delete this assignment? This will permanently remove all student submissions for this assignment as well."
        onConfirm={() => assignmentToDelete && handleDelete(assignmentToDelete)}
        confirmText="Delete"
        variant="destructive"
      />
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { collection, getDocs, query, where, doc, getDoc } from "firebase/firestore";
import { db, cleanupStudentData } from "@/lib/firebase";
import { useAuth } from "@/contexts/auth-context";
import { toast } from "sonner";
import { ConfirmDialog } from "@/components/ui/confirm-dialog";
import { Card, CardContent, CardHeader } from "@/components/ui/card";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Button } from "@/components/ui/button";
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuTrigger } from "@/components/ui/dropdown-menu";
import { TeacherPageHeader } from "@/components/teacher/workspace";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { ArrowUpRight, BarChart3, MoreHorizontal, Trash2 } from "lucide-react";
import Link from "next/link";
import { GradeExportButton } from "@/components/grade-export-button";
import { GradeDistributionChart } from "@/components/admin/grade-distribution-chart";

interface Student {
  id: string;
  name: string;
  email: string;
  submissionCount: number;
  averageScore: number;
  gradedCount: number;
}

export default function TeacherGradesPage() {
  const { user } = useAuth();
  const [courses, setCourses] = useState<{id: string, name: string, code: string}[]>([]);
  const [selectedCourseId, setSelectedCourseId] = useState<string>("all");
  const [students, setStudents] = useState<Student[]>([]);
  const [loading, setLoading] = useState(true);
  const [assignments, setAssignments] = useState<{id: string, title: string, courseId?: string}[]>([]);
  const [selectedAssignmentId, setSelectedAssignmentId] = useState<string>("all");
  const [assignmentsLoaded, setAssignmentsLoaded] = useState(false);
  const [showDistribution, setShowDistribution] = useState(false);
  const [studentToDelete, setStudentToDelete] = useState<string | null>(null);


  useEffect(() => {
    async function fetchCourses() {
        if (!user) return;
        try {
            const snap = await getDocs(query(collection(db, "courses"), where("teacherId", "==", user.uid)));
            const coursesData = snap.docs.map(d => ({ id: d.id, ...d.data() } as any));
            setCourses(coursesData);

            // If there's at least one course, select the first one by default 
            // instead of "All Classes" to satisfy "per class" requirement better
            if (coursesData.length > 0) {
                setSelectedCourseId(coursesData[0].id);
            }
        } catch (e) {
            console.error("Error fetching courses", e);
        }
    }
    fetchCourses();
  }, [user]);

  useEffect(() => {
    async function fetchAssignments() {
        if (!user) return;
        try {
            const snap = await getDocs(query(collection(db, "assignments"), where("teacherId", "==", user.uid)));
            setAssignments(snap.docs.map(d => ({ 
                id: d.id, 
                title: d.data().title,
                courseId: d.data().courseId
            })));
        } catch (e) {
            console.error("Error fetching assignments", e);
        } finally {
            setAssignmentsLoaded(true);
        }
    }
    fetchAssignments();
  }, [user]);


  useEffect(() => {
    async function fetchStudentsAndGrades() {
      if (!user) return;
      setLoading(true);
      try {
        // 1. Get relevant assignments based on filters
        let filteredAssignmentIds = assignments.map(a => a.id);
        if (selectedCourseId !== "all") {
            filteredAssignmentIds = assignments
                .filter(a => a.courseId === selectedCourseId)
                .map(a => a.id);
        }

        if (selectedAssignmentId !== "all") {
            filteredAssignmentIds = [selectedAssignmentId];
        }

        if (!assignmentsLoaded) {
            return;
        }

        if (filteredAssignmentIds.length === 0) {
            // No assignments for this teacher or filter combination
            setStudents([]);
            setLoading(false);
            return;
        }

        // 2. Query relevant submissions
        let submissionsDocs: any[] = [];
        if (selectedAssignmentId !== "all") {
            const snap = await getDocs(query(collection(db, "submissions"), where("assignmentId", "==", selectedAssignmentId)));
            submissionsDocs = snap.docs;
        } else {
            // CHUNKED FETCHING: Only fetch submissions for teacher's assignments
            // This is critical for security (prevent leaking all submissions) and performance.
            const chunks = [];
            for (let i = 0; i < filteredAssignmentIds.length; i += 30) {
                chunks.push(filteredAssignmentIds.slice(i, i + 30));
            }

            if (chunks.length > 0) {
               const results = await Promise.all(chunks.map(chunk => 
                  getDocs(query(collection(db, "submissions"), where("assignmentId", "in", chunk)))
               ));
               results.forEach(snap => submissionsDocs.push(...snap.docs));
            }
        }

        const studentMap = new Map<string, { name: string; email: string; scores: number[]; count: number }>();
        const validAssignmentIds = new Set(filteredAssignmentIds);


        // Fetch students in the course to cross-reference (if course selected)
        let courseStudentIds = new Set<string>();
        if (selectedCourseId !== "all") {
            const snap = await getDocs(query(collection(db, "users"), where("courseId", "==", selectedCourseId), where("role", "==", "student")));
            snap.docs.forEach(d => courseStudentIds.add(d.id));
        }

        submissionsDocs.forEach((doc) => {
          const data = doc.data();
          if (data.status === 'draft') return; 

          // Verify assignment belongs to filter
          if (!validAssignmentIds.has(data.assignmentId)) return;

          const studentId = data.studentId;

          // If course is selected, only show students in that course
          if (selectedCourseId !== "all" && !courseStudentIds.has(studentId)) return;

          if (!studentMap.has(studentId)) {
            studentMap.set(studentId, { 
              name: data.studentName || "Unknown Student", 
              email: data.studentEmail || "",
              scores: [],
              count: 0
            });
          }

          const student = studentMap.get(studentId)!;
          student.count++;
          if (data.graded && typeof data.score === "number" && Number.isFinite(data.score)) {
            student.scores.push(data.score);
          }
        });


        // 3. Populate names from student docs if missing
        const unknownStudents = Array.from(studentMap.entries())
          .filter(([_, data]) => data.name === "Unknown Student");

        await Promise.all(
          unknownStudents.map(async ([studentId, _]) => {
            try {
              // Try unified users
              const userDoc = await getDoc(doc(db, "users", studentId));
              if (userDoc.exists()) {
                const userData = userDoc.data();
                const student = studentMap.get(studentId);
                if (student) {
                  student.name = userData.displayName || userData.name || "Unknown Student";
                  student.email = userData.email || student.email;
                }
              }
            } catch (error) {
              console.error(`Error fetching student ${studentId}:`, error);
            }
          })
        );

        // Convert map to array
        const studentsArray: Student[] = Array.from(studentMap.entries()).map(([id, data]) => {
          const totalScore = data.scores.reduce((a, b) => a + b, 0);
          const averageScore = data.scores.length > 0 ? Math.round(totalScore / data.scores.length) : 0;

          return {
            id,
            name: data.name,
            email: data.email,
            submissionCount: data.count,
            averageScore,
            gradedCount: data.scores.length,
          };
        });

        setStudents(studentsArray);
      } catch (error) {
        console.error("Error fetching students:", error);
      } finally {
        setLoading(false);
      }
    }

    fetchStudentsAndGrades();
  }, [selectedAssignmentId, selectedCourseId, user, assignments, assignmentsLoaded]);


  const deleteStudent = async (studentId: string) => {
    try {
      // 1. Cleanup Storage and Submissions
      await cleanupStudentData(studentId, selectedCourseId === "all" ? undefined : selectedCourseId);

      setStudents(students.filter((s) => s.id !== studentId));
      toast.success("Student records removed.");
    } catch (error: any) {
      console.error("Error deleting student:", error);
      toast.error(`Failed to delete student: ${error.message}`);
    }
  };

  const selectedAssignmentTitle = assignments.find((assignment) => assignment.id === selectedAssignmentId)?.title;
  const gradedStudents = students.filter((student) => student.gradedCount > 0);

  return (
    <div className="space-y-6">
      <TeacherPageHeader title="Gradebook" description="Review student scores and submission history.">
        <GradeExportButton
          data={loading ? [] : students.map((student) => ({
            studentName: student.name,
            studentEmail: student.email,
            assignmentTitle: selectedAssignmentTitle || "All Assignments Summary",
            score: student.averageScore,
            totalPoints: 100,
            submittedAt: new Date().toLocaleDateString(),
          }))}
          filename={`grades-${selectedCourseId}-${new Date().toISOString().split("T")[0]}.csv`}
        />
      </TeacherPageHeader>

      <Card className="min-w-0 gap-0 py-0">
        <CardHeader className="flex flex-wrap items-end justify-between gap-4 px-4 py-4 sm:px-5">
          <div className="grid w-full gap-3 sm:w-auto sm:grid-cols-2">
            <div className="min-w-0 space-y-1.5">
              <label htmlFor="gradebook-class" className="block text-xs font-medium text-muted-foreground">Class</label>
              <Select
                value={selectedCourseId}
                onValueChange={(value) => {
                  setSelectedCourseId(value);
                  setSelectedAssignmentId("all");
                }}
              >
                <SelectTrigger id="gradebook-class" className="w-full cursor-pointer sm:w-44">
                  <SelectValue placeholder="All Classes" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All Classes</SelectItem>
                  {courses.map((course) => <SelectItem key={course.id} value={course.id}>{course.name}</SelectItem>)}
                </SelectContent>
              </Select>
            </div>
            <div className="min-w-0 space-y-1.5">
              <label htmlFor="gradebook-assignment" className="block text-xs font-medium text-muted-foreground">Assignment</label>
              <Select value={selectedAssignmentId} onValueChange={setSelectedAssignmentId}>
                <SelectTrigger id="gradebook-assignment" className="w-full cursor-pointer sm:w-52">
                  <SelectValue placeholder="All Assignments" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All Assignments</SelectItem>
                  {assignments.filter((assignment) => selectedCourseId === "all" || assignment.courseId === selectedCourseId)
                    .map((assignment) => <SelectItem key={assignment.id} value={assignment.id}>{assignment.title}</SelectItem>)}
                </SelectContent>
              </Select>
            </div>
          </div>
          <Button
            variant="ghost"
            size="sm"
            aria-expanded={showDistribution}
            aria-controls="grade-distribution"
            onClick={() => setShowDistribution((open) => !open)}
          >
            <BarChart3 />
            {showDistribution ? "Hide distribution" : "Grade distribution"}
          </Button>
        </CardHeader>
        <div className="border-t" id="grade-distribution" hidden={!showDistribution}>
          {showDistribution && (
            <GradeDistributionChart
              submissions={loading ? [] : gradedStudents.map((student) => ({ score: student.averageScore }))}
              title={selectedAssignmentTitle || "Grade distribution"}
              description="Students grouped by their average score"
            />
          )}
        </div>
        <CardContent className="border-t p-0">
          {loading || students.length === 0 ? (
            <p role="status" className="px-5 py-10 text-center text-sm text-muted-foreground">
              {loading ? "Loading grades…" : "No submissions match these filters."}
            </p>
          ) : (
            <Table aria-label="Student grades">
              <TableHeader className="bg-muted/40">
                <TableRow>
                  <TableHead className="pl-4 sm:pl-5">Student</TableHead>
                  <TableHead className="text-right">Submissions</TableHead>
                  <TableHead className="text-right">Average</TableHead>
                  <TableHead className="w-12"><span className="sr-only">Actions</span></TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {students.map((student) => (
                  <TableRow key={student.id}>
                    <TableCell className="max-w-64 whitespace-normal py-3 pl-4 sm:pl-5">
                      <Link
                        href={`/teacher/grades/student?studentId=${student.id}`}
                        className="inline-flex items-baseline gap-1.5 break-words font-medium hover:text-primary hover:underline"
                      >
                        {student.name} <ArrowUpRight aria-hidden="true" className="size-3 shrink-0 text-muted-foreground" />
                      </Link>
                      {student.email && <p className="break-all text-xs text-muted-foreground">{student.email}</p>}
                    </TableCell>
                    <TableCell className="text-right tabular-nums">{student.submissionCount}</TableCell>
                    <TableCell className="text-right font-medium tabular-nums">
                      {student.gradedCount ? `${student.averageScore}%` : <span aria-label="Awaiting a grade">—</span>}
                    </TableCell>
                    <TableCell className="pr-3">
                      <DropdownMenu>
                        <DropdownMenuTrigger asChild>
                          <Button variant="ghost" size="icon-sm" aria-label={`Actions for ${student.name}`}>
                            <MoreHorizontal />
                          </Button>
                        </DropdownMenuTrigger>
                        <DropdownMenuContent align="end">
                          <DropdownMenuItem variant="destructive" onSelect={() => setStudentToDelete(student.id)}>
                            <Trash2 /> Remove records
                          </DropdownMenuItem>
                        </DropdownMenuContent>
                      </DropdownMenu>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          )}
        </CardContent>
      </Card>

      <ConfirmDialog
        open={!!studentToDelete}
        onOpenChange={(open) => !open && setStudentToDelete(null)}
        title="Remove Student Records"
        description="Are you sure you want to remove this student from the gradebook? This will delete all their submissions and uploaded storage files to save space."
        onConfirm={() => studentToDelete && deleteStudent(studentToDelete)}
        confirmText="Remove"
        variant="destructive"
      />
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { useSearchParams } from "next/navigation";
import { collection, query, where, getDocs, getDoc, doc } from "firebase/firestore";
import { db } from "@/lib/firebase";
import { useAuth } from "@/contexts/auth-context";
import { Card, CardContent, CardHeader } from "@/components/ui/card";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Button } from "@/components/ui/button";
import { ArrowLeft, ChevronRight } from "lucide-react";
import Link from "next/link";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { TeacherPageHeader } from "@/components/teacher/workspace";
import { GradeExportButton } from "@/components/grade-export-button";
import { LoadingSpinner } from "@/components/ui/loading-spinner";

interface Submission {
  id: string;
  assignmentId: string;
  assignmentTitle: string;
  submittedAt: Date | null;
  score: number | null;
  graded: boolean;
}

interface AssignmentOption {
  id: string;
  title: string;
}

export default function StudentDetailsPage() {
  const { user } = useAuth();
  const searchParams = useSearchParams();
  const studentId = searchParams ? searchParams.get('studentId') ?? "" : "";
  const [submissions, setSubmissions] = useState<Submission[]>([]);
  const [studentName, setStudentName] = useState("Student");
  const [loading, setLoading] = useState(true);
  const [assignments, setAssignments] = useState<AssignmentOption[]>([]);
  const [selectedAssignment, setSelectedAssignment] = useState<string>("");

  useEffect(() => {
    if (!studentId || !user) {
      setLoading(false);
      return;
    }

    async function fetchStudentData() {
      try {
        // Fetch all assignments for filter dropdown (filtered by teacher)
        const assignmentsQuery = query(collection(db, "assignments"), where("teacherId", "==", user!.uid));
        const assignmentsSnapshot = await getDocs(assignmentsQuery);
        const assignmentOptions: AssignmentOption[] = assignmentsSnapshot.docs.map((doc) => ({
          id: doc.id,
          title: doc.data().title || "Untitled Assignment",
        }));
        setAssignments(assignmentOptions);

        // Allowed assignments set for validation
        const allowedAssignmentIdsArr = Array.from(new Set(assignmentsSnapshot.docs.map(d => d.id)));
        const allowedAssignmentIdsSet = new Set(allowedAssignmentIdsArr);

        // Fetch submissions for this student belonging to the teacher's assignments
        let submissionsDocs: any[] = [];
        if (allowedAssignmentIdsArr.length > 0) {
            const chunks = [];
            for (let i = 0; i < allowedAssignmentIdsArr.length; i += 30) {
                chunks.push(allowedAssignmentIdsArr.slice(i, i + 30));
            }

            const results = await Promise.all(chunks.map(chunk => 
                getDocs(query(collection(db, "submissions"), where("studentId", "==", studentId), where("assignmentId", "in", chunk)))
            ));
            results.forEach(snap => submissionsDocs.push(...snap.docs));
        }

        const processedSubmissions = await Promise.all(submissionsDocs.map(async (docSnapshot) => {
          const data = docSnapshot.data();

          // Verify assignment ownership (redundant but safe)
          if (!allowedAssignmentIdsSet.has(data.assignmentId)) return null;

          // Try to get student name from first submission if not available elsewhere
          if (data.studentName) setStudentName(data.studentName);

          // Fetch assignment title
          let assignmentTitle = "Unknown Assignment";
          let assignmentExists = false;
          if (data.assignmentId) {
             const assignment = assignmentOptions.find(a => a.id === data.assignmentId);
             if (assignment) {
                 assignmentTitle = assignment.title;
                 assignmentExists = true;
             }
          }

          if (!assignmentExists) return null;
          if (data.status === 'draft') return null;

          return {
            id: docSnapshot.id,
            assignmentId: data.assignmentId,
            assignmentTitle,
            submittedAt: data.submittedAt?.toDate?.() || (data.submittedAt ? new Date(data.submittedAt) : null),
            score: data.score,
            graded: data.graded,
          };
        }));

        setSubmissions(processedSubmissions.filter((s): s is Submission => s !== null));

      } catch (error) {
        console.error("Error fetching student data:", error);
      } finally {
        setLoading(false);
      }
    }

    fetchStudentData();
  }, [studentId, user]);

  if (loading) {
    return <LoadingSpinner fullPage />;
  }

  if (!studentId) {
    return (
      <div className="space-y-6">
        <div className="flex items-center gap-4">
          <Button asChild variant="ghost" size="icon">
            <Link href="/teacher/grades" aria-label="Back to grades">
              <ArrowLeft className="h-4 w-4" />
            </Link>
          </Button>
          <div>
            <h1 className="text-3xl font-bold">Error</h1>
            <p className="text-muted-foreground">No student ID provided.</p>
          </div>
        </div>
      </div>
    );
  }

  // Filter submissions by selected assignment
  const filteredSubmissions = selectedAssignment
    ? submissions.filter((s) => s.assignmentId === selectedAssignment)
    : submissions;

  return (
    <div className="space-y-6">
      <Link href="/teacher/grades" className="inline-flex items-center gap-2 text-sm text-muted-foreground hover:text-foreground">
        <ArrowLeft className="size-4" /> Gradebook
      </Link>

      <TeacherPageHeader title={studentName} description="Submission history and grades.">
        <GradeExportButton
          data={submissions.map((submission) => ({
            studentName,
            studentEmail: "—",
            assignmentTitle: submission.assignmentTitle,
            score: submission.score || 0,
            totalPoints: 100,
            submittedAt: submission.submittedAt?.toLocaleDateString() || "N/A",
          }))}
          filename={`grades-${studentName.replace(/\s+/g, "-")}-${new Date().toISOString().split("T")[0]}.csv`}
        />
      </TeacherPageHeader>

      <Card className="min-w-0 gap-0 py-0">
        <CardHeader className="flex flex-wrap items-end justify-between gap-3 px-4 py-4 sm:px-5">
          <h2 className="text-base font-semibold">Submissions</h2>
          <div className="w-full space-y-1.5 sm:w-52">
            <label htmlFor="student-assignment" className="block text-xs font-medium text-muted-foreground">Assignment</label>
            <Select value={selectedAssignment || "all"} onValueChange={(value) => setSelectedAssignment(value === "all" ? "" : value)}>
              <SelectTrigger id="student-assignment" className="w-full cursor-pointer">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">All Assignments</SelectItem>
                {assignments.map((assignment) => <SelectItem key={assignment.id} value={assignment.id}>{assignment.title}</SelectItem>)}
              </SelectContent>
            </Select>
          </div>
        </CardHeader>
        <CardContent className="border-t p-0">
          {filteredSubmissions.length === 0 ? (
            <p className="px-5 py-10 text-center text-sm text-muted-foreground">No submissions match this filter.</p>
          ) : (
            <Table aria-label="Student submissions">
              <TableHeader className="bg-muted/40">
                <TableRow>
                  <TableHead className="pl-4 sm:pl-5">Assignment</TableHead>
                  <TableHead>Score</TableHead>
                  <TableHead className="text-right pr-4 sm:pr-5">Review</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {filteredSubmissions.map((submission) => (
                  <TableRow key={submission.id}>
                    <TableCell className="max-w-72 whitespace-normal py-3 pl-4 sm:pl-5">
                      <p className="break-words font-medium">{submission.assignmentTitle}</p>
                      <p className="text-xs text-muted-foreground">{submission.submittedAt ? `Submitted ${submission.submittedAt.toLocaleDateString()}` : "No submission date"}</p>
                    </TableCell>
                    <TableCell className="font-medium tabular-nums">
                      {submission.graded ? (submission.score == null ? "—" : `${submission.score}%`) : <span className="text-muted-foreground">Pending</span>}
                    </TableCell>
                    <TableCell className="text-right pr-4 sm:pr-5">
                      <Button asChild variant={submission.graded ? "ghost" : "outline"} size="sm">
                        <Link href={`/teacher/submission/grade?id=${submission.id}`}>
                          {submission.graded ? "Review" : "Grade"} <ChevronRight />
                        </Link>
                      </Button>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

