"use client";

import { useEffect, useState } from "react";
import { useSearchParams } from "next/navigation";
import { collection, getDocs, query, where, deleteDoc, doc, getDoc, setDoc } from "firebase/firestore";
import { db, cleanupStudentData } from "@/lib/firebase";
import { useAuth } from "@/contexts/auth-context";
import { toast } from "sonner";
import { ConfirmDialog } from "@/components/ui/confirm-dialog";
import { Card, CardContent, CardHeader } from "@/components/ui/card";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Button } from "@/components/ui/button";
import { ArrowUpRight, MoreHorizontal, Trash2 } from "lucide-react";
import Link from "next/link";
import { RosterImport } from "@/components/roster-import";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { NetworkStudents } from "@/components/teacher/network-students";
import { TeacherPageHeader } from "@/components/teacher/workspace";
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuTrigger } from "@/components/ui/dropdown-menu";

interface Student {
  id: string;
  email: string;
  name?: string;
  createdAt?: Date;
  courseId?: string;
  courseName?: string;
}

export default function StudentsPage() {
  const { user, profile } = useAuth();
  const searchParams = useSearchParams();
  const [activeTab, setActiveTab] = useState(searchParams?.get("tab") || "roster");
  const [students, setStudents] = useState<Student[]>([]);
  const [loading, setLoading] = useState(true);
  const [studentToDelete, setStudentToDelete] = useState<string | null>(null);
  const [networkTeacherIds, setNetworkTeacherIds] = useState<string[]>([]);

  useEffect(() => {
    const tabParam = searchParams?.get("tab");
    if (tabParam === "insights" || tabParam === "roster") {
      setActiveTab(tabParam);
    }
  }, [searchParams]);

  useEffect(() => {
    async function fetchStudentsAndNetwork() {
      if (!user) return;
      try {
        setLoading(true);

        // Fetch department teachers if in an organization
        if (profile?.organizationId) {
          const membersSnap = await getDocs(query(
            collection(db, "users"),
            where("organizationId", "==", profile.organizationId),
            where("role", "==", "teacher")
          ));
          const teacherIds = membersSnap.docs.map(d => d.id);
          setNetworkTeacherIds(teacherIds.length > 0 ? teacherIds : [user.uid]);
        } else {
          setNetworkTeacherIds([user.uid]);
        }

        // Fetch courses first to map IDs (include legacy search too)
        const [cSnap1, cSnap2] = await Promise.all([
          getDocs(query(collection(db, "courses"), where("teacherId", "==", user.uid))),
          getDocs(query(collection(db, "courses"), where("teacherId", "==", user.uid), where("code", "==", user.uid)))
        ]);

        const courseMap: Record<string, string> = {};
        const myCourseIds = new Set<string>();
        const myCodes = new Set<string>();

        [...cSnap1.docs, ...cSnap2.docs].forEach(d => {
          courseMap[d.id] = d.data().name;
          myCourseIds.add(d.id);
          if (d.data().code) myCodes.add(d.data().code);
        });

        // Query unified collections to find students assigned to this teacher
        const [unifiedByUid, unifiedByCourses] = await Promise.all([
          getDocs(query(collection(db, "users"), where("teacherId", "==", user.uid), where("role", "==", "student"))).catch(() => ({ docs: [] } as any)),
          (myCourseIds.size > 0
            ? getDocs(query(collection(db, "users"), where("courseId", "in", Array.from(myCourseIds).slice(0, 30)), where("role", "==", "student")))
            : Promise.resolve({ docs: [] } as any)
          )
        ]);

        const studentsMap = new Map<string, Student>();
        const allDocs = [...unifiedByUid.docs, ...unifiedByCourses.docs];

        allDocs.forEach((doc) => {
          const sData = doc.data();
          const isOurStudent = sData.teacherId === user.uid || (sData.courseId && myCourseIds.has(sData.courseId));

          if (isOurStudent && !studentsMap.has(doc.id)) {
            studentsMap.set(doc.id, {
              id: doc.id,
              email: sData.email || "unknown@student.com",
              name: sData.displayName || sData.name || (sData.email ? sData.email.split("@")[0] : "Student"),
              createdAt: sData.createdAt?.toDate ? sData.createdAt.toDate() : (sData.createdAt ? new Date(sData.createdAt) : new Date()),
              courseId: sData.courseId,
              courseName: sData.courseId ? courseMap[sData.courseId] : undefined
            } as Student);
          }
        });

        setStudents(Array.from(studentsMap.values()));
      } catch (error) {
        console.error("Error fetching students:", error);
      } finally {
        setLoading(false);
      }
    }
    fetchStudentsAndNetwork();
  }, [user, profile]);

  const deleteStudent = async (studentId: string) => {
    try {
      await cleanupStudentData(studentId, undefined, true);
      setStudents(students.filter((s) => s.id !== studentId));
      toast.success("Student records removed.");
    } catch (error: any) {
      console.error("Error deleting student:", error);
      toast.error(`Failed to delete student: ${error.message}`);
    }
  };

  return (
    <div className="space-y-6">
      <TeacherPageHeader title="Students" description="Manage enrollments and explore how students use Raise.">
        {user && (
          <Button variant="outline" asChild>
            <Link href="/teacher">Manage Classes <ArrowUpRight /></Link>
          </Button>
        )}
        <RosterImport />
      </TeacherPageHeader>

      <Tabs value={activeTab} onValueChange={setActiveTab} className="min-w-0 gap-4">
        <TabsList className="h-auto max-w-full flex-wrap">
          <TabsTrigger value="roster" className="min-h-8">Roster</TabsTrigger>
          <TabsTrigger value="insights" className="min-h-8">Learning insights</TabsTrigger>
        </TabsList>

        <TabsContent value="roster">
          <Card className="min-w-0 gap-0 py-0">
            <CardHeader className="flex flex-wrap items-center justify-between gap-2 px-4 py-4 sm:px-5">
              <h2 className="text-base font-semibold">Class roster</h2>
              {!loading && <span className="text-sm text-muted-foreground">{students.length} enrolled</span>}
            </CardHeader>
            <CardContent className="border-t p-0">
              {loading || students.length === 0 ? (
                <p role="status" className="px-5 py-10 text-center text-sm text-muted-foreground">
                  {loading ? "Loading the roster…" : "No students enrolled yet. Share a class code or import a roster to get started."}
                </p>
              ) : (
                <Table aria-label="Class roster">
                  <TableHeader className="bg-muted/40">
                    <TableRow>
                      <TableHead className="pl-4 sm:pl-5">Student</TableHead>
                      <TableHead>Class</TableHead>
                      <TableHead className="w-12"><span className="sr-only">Actions</span></TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {students.map((student) => (
                      <TableRow key={student.id}>
                        <TableCell className="max-w-64 whitespace-normal py-3 pl-4 sm:pl-5">
                          <p className="break-words font-medium">{student.name || student.email.split("@")[0]}</p>
                          <p className="break-all text-xs text-muted-foreground">{student.email}</p>
                        </TableCell>
                        <TableCell className="max-w-48 whitespace-normal break-words text-muted-foreground">
                          {student.courseName || "No class assigned"}
                        </TableCell>
                        <TableCell className="pr-3">
                          <DropdownMenu>
                            <DropdownMenuTrigger asChild>
                              <Button variant="ghost" size="icon-sm" aria-label={`Actions for ${student.name || student.email}`}>
                                <MoreHorizontal />
                              </Button>
                            </DropdownMenuTrigger>
                            <DropdownMenuContent align="end">
                              <DropdownMenuItem variant="destructive" onSelect={() => setStudentToDelete(student.id)}>
                                <Trash2 /> Remove student
                              </DropdownMenuItem>
                            </DropdownMenuContent>
                          </DropdownMenu>
                        </TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              )}
            </CardContent>
          </Card>
        </TabsContent>

        <TabsContent value="insights">
          <NetworkStudents
            organizationId={profile?.organizationId || undefined}
            teacherIds={networkTeacherIds.length > 0 ? networkTeacherIds : (user ? [user.uid] : [])}
          />
        </TabsContent>
      </Tabs>

      <ConfirmDialog
        open={!!studentToDelete}
        onOpenChange={(open) => !open && setStudentToDelete(null)}
        title="Remove Student"
        description="Are you sure you want to remove this student? This will remove them from your class lists and delete their submissions to save storage space."
        onConfirm={() => studentToDelete && deleteStudent(studentToDelete)}
        confirmText="Remove"
        variant="destructive"
      />
    </div>
  );
}

"use client";
import { authenticatedFetch } from "@/lib/authenticated-fetch";
import { getTeacherAssignment } from "@/lib/authenticated-fetch";

import { useEffect, useState } from "react";
import { useSearchParams, useRouter } from "next/navigation";
import { doc, getDoc, updateDoc } from "firebase/firestore";
import { db, type WorkFile } from "@/lib/firebase";
import { getAssignmentPoints } from "@/lib/assignment-points";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Badge } from "@/components/ui/badge";
import { ArrowLeft, Save, FileText, Image as ImageIcon, Download, Brain, Sparkles, AlertTriangle, CheckCircle, XCircle } from "lucide-react";
import Link from "next/link";
import { LoadingSpinner } from "@/components/ui/loading-spinner";
import { motion, AnimatePresence } from "framer-motion";
import { MarkdownRenderer } from "@/components/markdown-renderer";
import { toast } from "sonner";
import { RaiseLogo } from "@/components/ui/raise-logo";

interface Question {
  id: string;
  text: string;
  type: "text" | "multiple-choice" | "true-false" | "short-answer";
  options?: string[];
  correctAnswer?: string;
  points: number;
}

interface Answer {
  questionId: string;
  questionText: string;
  answer: string;
  score?: number;
  feedback?: string;
  reasoning?: string;
}

interface User {
  id: string;
  name: string;
  organizationId: string;
}

interface Submission {
  id: string;
  assignmentId: string;
  studentId: string;
  studentName?: string;
  submittedAt: Date;
  answers: Answer[];
  score: number | null;
  graded: boolean;
  workFiles?: WorkFile[];
  unfocusCount?: number;
}

interface Assignment {
  id: string;
  title: string;
  questions: Question[];
}

export default function GradeSubmissionPage() {
  const searchParams = useSearchParams();
  const id = searchParams ? searchParams.get('id') ?? "" : "";
  const router = useRouter();
  const [submission, setSubmission] = useState<Submission | null>(null);
  const [assignment, setAssignment] = useState<Assignment | null>(null);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [gradingQuestion, setGradingQuestion] = useState<string | null>(null);
  const [grades, setGrades] = useState<Record<string, number>>({});
  const [feedback, setFeedback] = useState<Record<string, string>>({});
  const [aiReasoning, setAiReasoning] = useState<Record<string, string>>({});

  useEffect(() => {
    if (!id) {
      setLoading(false);
      return;
    }

    async function fetchSubmission() {
      try {
        const docSnap = await getDoc(doc(db, "submissions", id!));
        if (docSnap.exists()) {
          const data = docSnap.data();
          const sub = {
            id: docSnap.id,
            ...data,
            submittedAt: data.submittedAt?.toDate?.() || new Date(data.submittedAt),
          } as Submission;

          setSubmission(sub);

          // Fetch assignment details to get question metadata
          const assignmentDoc = await getTeacherAssignment(data.assignmentId);
          if (assignmentDoc.exists()) {
            setAssignment({ id: assignmentDoc.id, ...assignmentDoc.data() } as Assignment);
          }

          // Initialize grades and feedback
          const initialGrades: Record<string, number> = {};
          const initialFeedback: Record<string, string> = {};
          const initialReasoning: Record<string, string> = {};
          sub.answers.forEach((ans) => {
            if (ans.score !== undefined) initialGrades[ans.questionId] = ans.score;
            if (ans.feedback) initialFeedback[ans.questionId] = ans.feedback;
            if (ans.reasoning) initialReasoning[ans.questionId] = ans.reasoning;
          });
          setGrades(initialGrades);
          setFeedback(initialFeedback);
          setAiReasoning(initialReasoning);
        }
      } catch (error) {
        console.error("Error fetching submission:", error);
      } finally {
        setLoading(false);
      }
    }
    fetchSubmission();
  }, [id]);

  const handleAiGrade = async (questionId: string) => {
    if (!submission || !assignment) return;
    setGradingQuestion(questionId);

    try {
      // For now, we reuse the API or just call it for specific question
      // But the API grades the whole submission.
      // Let's create an "AI Assistant" effect or just call the grading API and refresh.
      // Actually, we can implement a specific AI grading logic here too.
      // But the best UX is to just trigger the global API if they want to re-evaluate everything
      // OR specifically grade one.

      const response = await authenticatedFetch('/api/grade', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ submissionId: submission.id })
      });

      if (response.ok) {
        // Refresh the submission data
        const docSnap = await getDoc(doc(db, "submissions", submission.id));
        if (docSnap.exists()) {
          const updatedSub = docSnap.data() as Submission;
          const initialGrades: Record<string, number> = {};
          const initialFeedback: Record<string, string> = {};
          const initialReasoning: Record<string, string> = {};

          updatedSub.answers.forEach((ans) => {
            if (ans.score !== undefined) initialGrades[ans.questionId] = ans.score;
            if (ans.feedback) initialFeedback[ans.questionId] = ans.feedback;
            if (ans.reasoning) initialReasoning[ans.questionId] = ans.reasoning;
          });

          setGrades(initialGrades);
          setFeedback(initialFeedback);
          setAiReasoning(initialReasoning);
          setSubmission({ ...submission, answers: updatedSub.answers });
          toast.success("AI grading complete!");
        }
      } else {
        let errMsg = "AI grading failed.";
        try {
          const errData = await response.json();
          errMsg = errData.error || errMsg;
        } catch (e) {
          errMsg = `AI Grading API error (${response.status})`;
        }
        throw new Error(errMsg);
      }
    } catch (error: any) {
      console.error("AI Grading failed:", error);
      toast.error(error.message || "AI grading failed. Please check your account budget.");
    } finally {
      setGradingQuestion(null);
    }
  };

  const totalPossiblePoints = getAssignmentPoints(assignment?.questions);
  const totalEarnedPoints = assignment?.questions?.reduce((earned, question) => earned + (grades[question.id] || 0), 0) ?? 0;
  const percentageScore = totalPossiblePoints > 0
    ? Math.round((totalEarnedPoints / totalPossiblePoints) * 100)
    : 0;

  const handleSave = async () => {
    if (!submission || !id || !assignment) return;
    setSaving(true);

    try {
      // Update answers with new grades/feedback
      const updatedAnswers = submission.answers.map(ans => ({
        ...ans,
        score: grades[ans.questionId] || 0,
        feedback: feedback[ans.questionId] || "",
        reasoning: aiReasoning[ans.questionId] || ""
      }));

      await updateDoc(doc(db, "submissions", id), {
        answers: updatedAnswers,
        score: percentageScore,
        earnedPoints: totalEarnedPoints,
        totalPoints: totalPossiblePoints,
        totalEarnedPoints,
        totalPossiblePoints,
        graded: true,
        gradedAt: new Date()
      });

      router.back();
    } catch (error) {
      console.error("Error saving grades:", error);
    } finally {
      setSaving(false);
    }
  };

  if (loading) {
    return <LoadingSpinner fullPage />;
  }

  if (!id) {
    return (
      <div className="max-w-4xl mx-auto space-y-6">
        <div className="flex items-center gap-4">
          <Button variant="ghost" size="icon" onClick={() => router.back()}>
            <ArrowLeft className="h-4 w-4" />
          </Button>
          <div>
            <h1 className="text-3xl font-bold">Error</h1>
            <p className="text-muted-foreground">No submission ID provided.</p>
          </div>
        </div>
      </div>
    );
  }

  if (!submission) {
    return <div className="flex items-center justify-center min-h-[50vh] w-full text-muted-foreground">Submission not found</div>;
  }

  return (
    <div className="max-w-5xl mx-auto space-y-8 pb-20">
      {/* Integrity Alert */}
      {submission.unfocusCount !== undefined && submission.unfocusCount > 0 && (
        <motion.div
          initial={{ opacity: 0, y: -20 }}
          animate={{ opacity: 1, y: 0 }}
        >
          <Card className="bg-yellow-50 border-yellow-200 dark:bg-yellow-950/20 dark:border-yellow-900">
            <CardHeader className="py-3">
              <div className="flex items-center gap-3">
                <AlertTriangle className="h-5 w-5 text-yellow-600" />
                <div>
                  <CardTitle className="text-yellow-800 dark:text-yellow-500 text-sm font-bold">Integrity Alert</CardTitle>
                  <CardDescription className="text-yellow-700 dark:text-yellow-400/80 text-xs">
                    Student switched tabs <span className="font-bold">{submission.unfocusCount}</span> time{submission.unfocusCount === 1 ? '' : 's'}. This may indicate searching for answers.
                  </CardDescription>
                </div>
              </div>
            </CardHeader>
          </Card>
        </motion.div>
      )}

      {/* Header */}
      <div className="flex flex-col md:flex-row md:items-end justify-between gap-6 px-4">
        <div className="space-y-4">
          <Button 
            variant="ghost" 
            size="sm" 
            onClick={() => router.back()}
            className="text-muted-foreground hover:text-foreground -ml-2"
          >
            <ArrowLeft className="h-4 w-4 mr-2" />
            Back to Submissions
          </Button>
          <div className="space-y-1">
            <div className="flex items-center gap-3">
              <Badge variant="outline" className="text-[10px] tracking-wider uppercase">
                Grading Terminal
              </Badge>
              <div className="h-1 w-1 rounded-full bg-muted-foreground/30" />
              <span className="text-xs text-muted-foreground">Submission ID: {submission.id.slice(0, 8)}</span>
            </div>
            <h1 className="text-3xl font-bold tracking-tight">
              {submission.studentName || "Student Submission"}
            </h1>
            <p className="text-muted-foreground text-sm">
              Submitted on {submission.submittedAt.toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric' })}
            </p>
          </div>
        </div>

        <div className="flex flex-col sm:flex-row gap-3">
          <Button 
            onClick={() => handleAiGrade('all')} 
            variant="outline"
            disabled={gradingQuestion === 'all'}
            size="sm"
          >
            {gradingQuestion === 'all' ? (
              <Sparkles className="h-4 w-4 mr-2 animate-spin" />
            ) : (
              <RaiseLogo size={16} className="text-foreground" />
            )}
            Re-grade with Raise
          </Button>
          <Button 
            onClick={handleSave} 
            disabled={saving}
            size="sm"
          >
            <Save className="h-4 w-4 mr-2" />
            {saving ? "Saving..." : "Save Grades"}
          </Button>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 px-4">
        <div className="lg:col-span-2 space-y-8">
          <AnimatePresence>
            {submission.answers.map((ans, index) => {
              const question = assignment?.questions?.find(q => q.id === ans.questionId);
              const isMCQOrTrueFalse = question?.type === "multiple-choice" || question?.type === "true-false";
              const maxPoints = question?.points || 10;
              const isGrading = gradingQuestion === ans.questionId || gradingQuestion === 'all';

              return (
                <motion.div
                  key={ans.questionId}
                  initial={{ opacity: 0, x: -20 }}
                  animate={{ opacity: 1, x: 0 }}
                  transition={{ delay: index * 0.1 }}
                >
                  <Card className="overflow-hidden border-zinc-200/50 dark:border-zinc-800/50 shadow-sm transition-all hover:shadow-md hover:border-zinc-300 dark:hover:border-zinc-700">
                    <div className="flex flex-col">
                      {/* Sub-Header */}
                      <div className="bg-muted/30 px-6 py-3 border-b flex items-center justify-between">
                        <div className="flex items-center gap-3">
                          <div className="h-6 w-6 rounded-md bg-foreground flex items-center justify-center text-[10px] font-bold text-background">
                            {index + 1}
                          </div>
                          <Badge variant="secondary" className="text-[10px] font-bold uppercase">
                            {question?.type || "Question"}
                          </Badge>
                        </div>
                        <div className="flex items-center gap-2">
                           <Badge variant="outline" className="text-[10px] border-muted-foreground/30">
                             Max Points: {maxPoints}
                           </Badge>
                        </div>
                      </div>

                      <CardContent className="p-6 space-y-6">
                        {/* Question Text */}
                        <div className="space-y-2">
                          <Label className="text-[10px] uppercase font-bold text-muted-foreground">Original Question</Label>
                          <div className="prose prose-zinc dark:prose-invert max-w-none text-sm">
                            <MarkdownRenderer noProse>
                              {ans.questionText}
                            </MarkdownRenderer>
                          </div>
                        </div>

                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                          {/* Student Answer */}
                          <div className="space-y-3 bg-muted/20 p-4 rounded-lg border">
                            <Label className="text-[10px] uppercase font-bold text-muted-foreground">Student Answer</Label>
                            <div className="prose prose-sm dark:prose-invert max-w-none min-h-[40px]">
                              {ans.answer ? (
                                <MarkdownRenderer noProse>
                                  {ans.answer}
                                </MarkdownRenderer>
                              ) : (
                                <span className="text-muted-foreground italic text-xs">No response provided.</span>
                              )}
                            </div>
                          </div>

                          {/* Correct Answer Reference */}
                          {question?.correctAnswer && (
                            <div className="space-y-3 bg-emerald-50/50 dark:bg-emerald-950/20 p-4 rounded-lg border border-emerald-200 dark:border-emerald-800">
                              <Label className="text-[10px] uppercase font-bold text-emerald-700 dark:text-emerald-400 flex items-center gap-2">
                                <CheckCircle className="h-3 w-3" />
                                Correct Answer Reference
                              </Label>
                              <div className="prose prose-sm dark:prose-invert max-w-none text-foreground/80">
                                <MarkdownRenderer noProse>
                                  {question.correctAnswer}
                                </MarkdownRenderer>
                              </div>
                            </div>
                          )}
                        </div>

                        {/* AI Analysis */}
                        {(aiReasoning[ans.questionId] || isGrading) && (
                          <div className="bg-primary/5 border border-primary/10 rounded-lg p-5 space-y-4">
                            <div className="flex items-center justify-between">
                              <div className="flex items-center gap-2">
                                <Sparkles className="h-4 w-4 text-primary" />
                                <span className="text-[10px] uppercase font-bold text-primary">AI Reasoning / Grading logic</span>
                              </div>
                              {isGrading && (
                                <div className="flex items-center gap-2 text-[10px] font-medium text-primary animate-pulse">
                                  AI is grading...
                                </div>
                              )}
                            </div>
                            {!isGrading && aiReasoning[ans.questionId] && (
                              <div className="text-sm text-foreground/80 leading-relaxed italic">
                                "{aiReasoning[ans.questionId]}"
                              </div>
                            )}
                          </div>
                        )}

                        {/* Teacher Inputs */}
                        <div className="pt-4 border-t space-y-6">
                           <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
                              <div className="space-y-2">
                                <Label className="text-[10px] uppercase font-bold text-muted-foreground">Points Earned</Label>
                                {isMCQOrTrueFalse ? (
                                  <div className="flex flex-col gap-2">
                                    <Button
                                      variant={grades[ans.questionId] === maxPoints ? "default" : "outline"}
                                      size="sm"
                                      className="h-10 text-xs"
                                      onClick={() => setGrades({ ...grades, [ans.questionId]: maxPoints })}
                                    >
                                      Correct
                                    </Button>
                                    <Button
                                      variant={grades[ans.questionId] === 0 ? "destructive" : "outline"}
                                      size="sm"
                                      className="h-10 text-xs"
                                      onClick={() => setGrades({ ...grades, [ans.questionId]: 0 })}
                                    >
                                      Incorrect
                                    </Button>
                                  </div>
                                ) : (
                                  <div className="relative group">
                                    <Input
                                      type="number"
                                      value={grades[ans.questionId] ?? ""}
                                      onChange={(e) => {
                                        const val = parseFloat(e.target.value) || 0;
                                        setGrades({ ...grades, [ans.questionId]: Math.min(val, maxPoints) });
                                      }}
                                      className="h-10 bg-background rounded-lg font-mono text-base pr-12"
                                    />
                                    <div className="absolute right-3 top-1/2 -translate-y-1/2 text-xs text-muted-foreground">
                                      / {maxPoints}
                                    </div>
                                  </div>
                                )}
                              </div>
                              <div className="md:col-span-3 space-y-2">
                                 <Label className="text-[10px] uppercase font-bold text-muted-foreground">Feedback for Student</Label>
                                 <Textarea
                                   value={feedback[ans.questionId] || ""}
                                   onChange={(e) => setFeedback({ ...feedback, [ans.questionId]: e.target.value })}
                                   className="min-h-[100px] bg-background rounded-lg resize-none"
                                   placeholder="Add any specific feedback for the student..."
                                 />
                              </div>
                           </div>
                        </div>
                      </CardContent>
                    </div>
                  </Card>
                </motion.div>
              );
            })}
          </AnimatePresence>
        </div>

        {/* Sidebar (Right) */}
        <div className="space-y-6">
          <div className="sticky top-6 space-y-6">
            <Card className="shadow-lg border-primary/10">
              <CardHeader className="pb-2">
                <CardTitle className="text-xs uppercase tracking-wider text-muted-foreground">Overall Score</CardTitle>
                <CardDescription className="text-[10px]">Points and percentage</CardDescription>
              </CardHeader>
              <CardContent className="space-y-6">
                <div className="flex items-baseline gap-2">
                  <span className="text-5xl font-bold tracking-tight">
                    {totalEarnedPoints.toLocaleString()}
                  </span>
                  <span className="text-xl text-muted-foreground">/ {totalPossiblePoints} points</span>
                </div>
                <div className="space-y-2">
                  <div className="flex justify-between text-xs">
                    <span className="text-muted-foreground">Percentage</span>
                    <span className="font-bold">{percentageScore}%</span>
                  </div>
                  <div className="h-2 w-full bg-muted rounded-full overflow-hidden">
                    <motion.div 
                      className="h-full bg-primary" 
                      initial={{ width: 0 }}
                      animate={{ width: `${percentageScore}%` }}
                      transition={{ duration: 0.5 }}
                    />
                  </div>
                </div>
                <div className="space-y-1 border-t pt-4">
                  <p className="text-[10px] uppercase font-bold text-muted-foreground tracking-wider">Status</p>
                  <p className="text-sm font-medium">{percentageScore >= 60 ? "Passing" : "Needs Review"}</p>
                </div>
              </CardContent>
            </Card>

            {/* Work Files Section */}
            {submission.workFiles && submission.workFiles.length > 0 && (
              <Card>
                <CardHeader>
                  <CardTitle className="text-sm font-bold flex items-center gap-2">
                    <FileText className="h-4 w-4" />
                    Student Work
                  </CardTitle>
                </CardHeader>
                <CardContent className="space-y-3">
                  {submission.workFiles.map((file, index) => (
                    <div key={index} className="group p-2 bg-muted/30 border rounded-lg hover:border-primary/50 transition-all">
                      <div className="flex items-center justify-between">
                        <div className="flex items-center gap-2 overflow-hidden">
                          {file.type === "application/pdf" ? (
                            <FileText className="h-4 w-4 text-red-500 shrink-0" />
                          ) : (
                            <ImageIcon className="h-4 w-4 text-primary shrink-0" />
                          )}
                          <p className="text-xs font-medium truncate w-32">{file.name}</p>
                        </div>
                        <Button 
                          variant="ghost" 
                          size="icon" 
                          className="h-8 w-8"
                          onClick={() => {
                            const link = document.createElement('a');
                            link.href = file.url;
                            link.download = file.name;
                            link.click();
                          }}
                        >
                          <Download className="h-4 w-4" />
                        </Button>
                      </div>
                      {file.type.startsWith('image/') && (
                        <div className="mt-2 relative">
                          <img src={file.url} alt={file.name} className="w-full h-24 object-cover rounded" />
                        </div>
                      )}
                    </div>
                  ))}
                </CardContent>
              </Card>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

"use client";

import { useState, useEffect, useRef } from "react";
import { collection, addDoc, getDocs, deleteDoc, doc, query, orderBy, where } from "firebase/firestore";
import { db, uploadFilesToStorage } from "@/lib/firebase";
import { useAuth } from "@/contexts/auth-context";
import { toast } from "sonner";
import { ConfirmDialog } from "@/components/ui/confirm-dialog";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Trash2, ExternalLink, Plus, Upload, FileText, Search } from "lucide-react";

import { TeacherPageHeader } from "@/components/teacher/workspace";
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";

interface Resource {
  id: string;
  title: string;
  url: string;
  type?: "video" | "document" | "link";
  courseId?: string;
  createdAt: any;
}

export default function ResourcesPage() {
  const { user } = useAuth();
  const [resources, setResources] = useState<Resource[]>([]);
  const [courses, setCourses] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [addOpen, setAddOpen] = useState(false);
  const fileInput = useRef<HTMLInputElement>(null);
  const [title, setTitle] = useState("");
  const [url, setUrl] = useState("");
  const [type, setType] = useState<string>("link");
  const [file, setFile] = useState<File | null>(null);
  const [selectedCourseId, setSelectedCourseId] = useState<string>("all");
  const [filterCourseId, setFilterCourseId] = useState<string>("all");
  const [searchQuery, setSearchQuery] = useState("");
  const [adding, setAdding] = useState(false);
  const [uploadProgress, setUploadProgress] = useState<number>(0);
  const [resourceToDelete, setResourceToDelete] = useState<string | null>(null);

  useEffect(() => {
    if (user) {
      fetchResources();
      fetchCourses();
    }
  }, [user]);

  async function fetchCourses() {
    if (!user) return;
    try {
      const q = query(collection(db, "courses"), where("teacherId", "==", user.uid));
      const snap = await getDocs(q);
      setCourses(snap.docs.map(d => ({ id: d.id, ...d.data() })));
    } catch (e) { console.error(e); }
  }

  async function fetchResources() {
    if (!user) return;
    try {
      const q = query(
        collection(db, "resources"), 
        where("teacherId", "==", user.uid),
        orderBy("createdAt", "desc")
      );
      const querySnapshot = await getDocs(q);
      const resourceList = querySnapshot.docs.map((doc) => ({
        id: doc.id,
        ...doc.data(),
      })) as Resource[];
      setResources(resourceList);
    } catch (error) {
      console.error("Error fetching resources:", error);
    } finally {
      setLoading(false);
    }
  }

  async function handleAddResource(e: React.FormEvent) {
    e.preventDefault();
    if (adding || !title || (!url && !file) || !user) return;

    setAdding(true);
    try {
      let finalUrl = url;
      let finalType = type;

      if (file) {
        setUploadProgress(10);
        const uploadedFiles = await uploadFilesToStorage([file], user.uid, (_, progress) => {
          setUploadProgress(progress);
        });
        if (uploadedFiles.length > 0) {
          finalUrl = uploadedFiles[0].url;
          // Auto-assign type if it's a file
          if (file.type.startsWith("video/")) finalType = "video";
          else finalType = "document";
        }
      } else if (url.includes("youtube.com") || url.includes("youtu.be") || url.includes("vimeo.com")) {
        finalType = "video";
      }

      await addDoc(collection(db, "resources"), {
        title,
        url: finalUrl,
        type: finalType,
        teacherId: user.uid,
        courseId: selectedCourseId === "all" ? null : selectedCourseId,
        createdAt: new Date(),
      });
      setTitle("");
      setUrl("");
      setFile(null);
      setType("link");
      setUploadProgress(0);
      setAddOpen(false);
      toast.success("Resource added successfully!");
      await fetchResources();
    } catch (error) {
      console.error("Error adding resource:", error);
      toast.error("Error adding resource. Please check your connection and try again.");
    } finally {
      setAdding(false);
    }
  }

  async function handleDelete(id: string) {
    try {
      await deleteDoc(doc(db, "resources", id));
      setResources(resources.filter((r) => r.id !== id));
      toast.success("Resource deleted!");
    } catch (error) {
      console.error("Error deleting resource:", error);
      toast.error("Error deleting resource.");
    }
  }

  const search = searchQuery.trim().toLowerCase();
  const filteredResources = resources.filter((resource) =>
    (filterCourseId === "all" || resource.courseId === filterCourseId)
    && (resource.title.toLowerCase().includes(search) || resource.url.toLowerCase().includes(search))
  );

  return (
    <div className="space-y-6">
      <TeacherPageHeader title="Resource Uploads" description="Share files, videos, and links with your classes.">
        <Dialog open={addOpen} onOpenChange={(open) => { if (!adding) setAddOpen(open); }}>
          <DialogTrigger asChild>
            <Button><Plus /> Add Resource</Button>
          </DialogTrigger>
          <DialogContent className="max-h-[90dvh] overflow-y-auto sm:max-w-lg">
            <DialogHeader>
              <DialogTitle>Add resource</DialogTitle>
              <DialogDescription>Upload a file or link to an online resource.</DialogDescription>
            </DialogHeader>
            <form onSubmit={handleAddResource} className="grid gap-4">
              <div className="grid gap-2">
                <Label htmlFor="resource-title">Title</Label>
                <Input id="resource-title" placeholder="e.g. Chapter 1 notes" value={title}
                  onChange={(event) => setTitle(event.target.value)} required disabled={adding} />
              </div>
              <div className="grid gap-4 sm:grid-cols-2">
                <div className="grid min-w-0 gap-2">
                  <Label htmlFor="resource-course">Class</Label>
                  <Select value={selectedCourseId} onValueChange={setSelectedCourseId} disabled={adding}>
                    <SelectTrigger id="resource-course" className="w-full cursor-pointer"><SelectValue /></SelectTrigger>
                    <SelectContent>
                      <SelectItem value="all">All Classes</SelectItem>
                      {courses.map((course) => <SelectItem key={course.id} value={course.id}>{course.name}</SelectItem>)}
                    </SelectContent>
                  </Select>
                </div>
                <div className="grid min-w-0 gap-2">
                  <Label htmlFor="resource-type">Type</Label>
                  <Select value={type} onValueChange={setType} disabled={adding}>
                    <SelectTrigger id="resource-type" className="w-full cursor-pointer"><SelectValue /></SelectTrigger>
                    <SelectContent>
                      <SelectItem value="link">Website</SelectItem>
                      <SelectItem value="document">Document</SelectItem>
                      <SelectItem value="video">Video</SelectItem>
                    </SelectContent>
                  </Select>
                </div>
              </div>
              <div className="grid gap-2">
                <Label htmlFor="resource-url">Link or file</Label>
                <div className="flex flex-wrap items-center gap-2">
                  <Input id="resource-url" placeholder="https://…" value={url}
                    className="min-w-32 flex-1" disabled={!!file || adding}
                    onChange={(event) => setUrl(event.target.value)} />
                  <input ref={fileInput} type="file" hidden onChange={(event) => {
                    const selected = event.target.files?.[0];
                    if (!selected) return;
                    setFile(selected);
                    setUrl("");
                    if (!title) setTitle(selected.name.replace(/\.[^/.]+$/, ""));
                  }} />
                  <Button type="button" variant="outline" disabled={adding} onClick={() => fileInput.current?.click()}>
                    <Upload /> Choose File
                  </Button>
                </div>
                {file && (
                  <div className="flex items-center gap-2 rounded-lg bg-muted px-3 py-2 text-sm">
                    <FileText aria-hidden="true" className="size-4 shrink-0 text-muted-foreground" />
                    <span className="min-w-0 flex-1 truncate" title={file.name}>{file.name}</span>
                    <Button type="button" size="sm" variant="ghost" disabled={adding} onClick={() => {
                      setFile(null);
                      if (fileInput.current) fileInput.current.value = "";
                    }}>Remove</Button>
                  </div>
                )}
              </div>
              <DialogFooter>
                <Button type="submit" disabled={adding || !title || (!url && !file)}>
                  {adding ? (file && uploadProgress < 100 ? `Uploading (${Math.round(uploadProgress)}%)…` : "Adding…") : "Add Resource"}
                </Button>
              </DialogFooter>
            </form>
          </DialogContent>
        </Dialog>
      </TeacherPageHeader>

      <Card className="min-w-0 gap-0 py-0">
        <CardHeader className="flex flex-wrap items-center justify-between gap-3 px-4 py-4 sm:px-5">
          <h2 className="text-base font-semibold">Resource archive</h2>
          <div className="flex w-full flex-wrap gap-2 sm:w-auto">
            <div className="relative w-full sm:w-48">
              <Search aria-hidden="true" className="absolute left-2.5 top-2.5 size-4 text-muted-foreground" />
              <Input aria-label="Search resources" placeholder="Search resources…" className="pl-8"
                value={searchQuery} onChange={(event) => setSearchQuery(event.target.value)} />
            </div>
            <Select value={filterCourseId} onValueChange={setFilterCourseId}>
              <SelectTrigger aria-label="Filter resources by class" className="w-full cursor-pointer sm:w-40"><SelectValue /></SelectTrigger>
              <SelectContent>
                <SelectItem value="all">All Classes</SelectItem>
                {courses.map((course) => <SelectItem key={course.id} value={course.id}>{course.name}</SelectItem>)}
              </SelectContent>
            </Select>
          </div>
        </CardHeader>
        <CardContent className="border-t p-0">
          {loading || filteredResources.length === 0 ? (
            <p role="status" className="px-5 py-10 text-center text-sm text-muted-foreground">
              {loading ? "Loading resources…" : resources.length === 0 ? "No resources yet." : "No resources match these filters."}
            </p>
          ) : (
            <Table aria-label="Resource archive">
              <TableHeader className="bg-muted/40">
                <TableRow>
                  <TableHead className="pl-4 sm:pl-5">Resource</TableHead>
                  <TableHead>Class</TableHead>
                  <TableHead className="w-12"><span className="sr-only">Actions</span></TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {filteredResources.map((resource) => (
                  <TableRow key={resource.id}>
                    <TableCell className="max-w-72 whitespace-normal py-3 pl-4 sm:pl-5">
                      <a href={resource.url} target="_blank" rel="noopener noreferrer"
                        className="inline-flex items-baseline gap-1.5 break-words font-medium hover:text-primary hover:underline"
                        title={resource.url}>
                        {resource.title} <ExternalLink aria-hidden="true" className="size-3 shrink-0 text-muted-foreground" />
                      </a>
                      <p className="text-xs capitalize text-muted-foreground">
                        {resource.type || "Link"} · {resource.createdAt?.toDate ? resource.createdAt.toDate().toLocaleDateString() : "Recently added"}
                      </p>
                    </TableCell>
                    <TableCell className="max-w-48 whitespace-normal break-words text-muted-foreground">
                      {resource.courseId ? courses.find((course) => course.id === resource.courseId)?.name || "Unknown class" : "All classes"}
                    </TableCell>
                    <TableCell className="pr-3">
                      <Button variant="ghost" size="icon-sm" aria-label={`Delete ${resource.title}`}
                        className="text-muted-foreground hover:text-destructive"
                        onClick={() => setResourceToDelete(resource.id)}>
                        <Trash2 />
                      </Button>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          )}
        </CardContent>
      </Card>

      <ConfirmDialog
        open={!!resourceToDelete}
        onOpenChange={(open) => !open && setResourceToDelete(null)}
        title="Delete Resource"
        description="Are you sure you want to delete this resource? This action cannot be undone."
        onConfirm={() => resourceToDelete && handleDelete(resourceToDelete)}
        confirmText="Delete"
        variant="destructive"
      />
    </div>
  );
}

"use client";
import { getTeacherAssignment } from "@/lib/authenticated-fetch";

import { useEffect, useState } from "react";
import { collection, getDocs, query, where } from "firebase/firestore";
import { db } from "@/lib/firebase";
import { useAuth } from "@/contexts/auth-context";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardFooter, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import { Tabs, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Search, Copy, Globe, Users, Lock, Loader2, Sparkles, Waypoints, Filter, ArrowUpRight, Clock, Star, MapPinned } from "lucide-react";
import { useRouter } from "next/navigation";
import Link from "next/link";
import { toast } from "sonner";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
