const apiReq = (
  path: string,
  user: string | null,
  body?: unknown,
  method = 'POST',
  extraHeaders: Record<string, string> = {}
) =>
  new NextRequest(`http://localhost/api/${path}`, {
    method,
    headers: {
      ...(user ? { Authorization: `Bearer ${user}` } : {}),
      'Content-Type': 'application/json',
      ...extraHeaders,
    },
    ...(body !== undefined ? { body: JSON.stringify(body) } : {}),
  });

